INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261384316', 'Kit Jacques Janine Hair Care Pistachio Shampoo 450ml + Condicionador 440ml', 'Kit Jacques Janine Hair Care Pistachio Shampoo 450ml + Condicionador 440ml O Kit Jacques Janine Hair Care Pistachio Shampoo 450ml + Condicionador 440ml é geralmente descrito como um conjunto que proporciona limpeza e nutrição para os cabelos, com uma fragrância agradável e diferenciada de pistache (ou pistachio). Ação: Oferece uma combinação de limpeza eficaz (shampoo) e hidratação/nutrição (condicionador). Fragrância: Característica marcante do kit é o irresistível aroma de pistache. Benefícios Comuns (dependendo da formulação específica): Nutrição profunda. Hidratação. Fios macios e revitalizados. Brilho. É um kit que busca transformar a rotina de cuidados capilares em um momento de luxo e eficiência, sendo geralmente adequado para todos os tipos de cabelo.', 68.99, 68.99, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-823pz-mopfmrzy72tn1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1331826475%2F58261384316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
