INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17301946476', 'Filme BOPP Antirrisco Fosco Mimo - 31 cm x 50 m - 30 mic', 'Plástico BOPP para Laminação na Mimo Stamping O Filme BOPP Antirrisco Fosco Mimo tem qualidade premium para fazer laminação perfeita em personalizados usando a laminadora Mimo Stamping. Ele tem 30 mic de espessura, o que o torna mais resistente. Além disso, esse BOPP para laminação a quente da Mimo pode ser aplicado em vários tipos de papéis com ou sem impressão a jato de tinta, a laser ou offset. Uma das vantagens é que o BOPP Mimo protege o papel contra umidade. Ele é transparente, tem acabamento especial antirrisco fosco e vem em um rolo compacto e fácil de usar de 31 cm x 50 m. Como Fazer Laminação a Quente com a Laminadora Mimo Stamping Coloque esse BOPP antirrisco fosco da Mimo sobre o papel a ser laminado. Coloque esse conjunto dentro da Base de Aplicação Mimo Stamping e então passe tudo junto pela laminadora Mimo Stamping no ajuste 3. Assim, com rapidez e praticidade, você vai laminar capas de agendas, planners, convites, álbuns e mais. Informações Técnicas: Produto: Filme BOPP Antirrisco Fosco Mimo - 31 cm x 50 m - 30 mic Cor: Transparente Acabamento: Antirrisco Fosco Espessura: 30 mic Formato: Rolo Tamanho: 31 cm x 50 m Temperatura de Aplicação: 110 a 125º C Aplicação Recomendada: com a Laminadora Mimo Stamping no Ajuste 3 Vantagem: Protege o papel contra Umidade Marca: Mimo Crafts: Código de Fábrica (SKU): 06070', 156.45, 156.45, NULL, 'Stationery > Art Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-23030-j1up7ix8ivova8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F660248852%2F17301946476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897493953', 'Cano Água ASTRA 1999/2011 - 65939 - 087165', 'Cano Água ASTRA 1999/2011 1.8/2.0/2.4 8v O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 49.08, 49.08, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rbni-lnra7ev7bemg9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20897493953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298011440', 'Ventilador Osc Parede 60cm Preto Bivolt Potente 200w Premium Ventisol Cor Da Estrutura Preta 127v/220v', 'VENTILADOR MAIS POTENTE DA MARCA VENTISOL! 100% ORIGINAL COM NOTA FISCAL! Sua empresa ou instituição com o ar mais refrescante. Para grandes áreas que precisem de ventilação, o Ventilador de Parede Ventisol 60cm é ideal. Indicado para grandes ambientes como lojas, escolas, restaurantes, igrejas, indústrias, entre outros. Ideal para grandes espaços: Lojas, escolas, igrejas, restaurantes, indústrias, ambientes que precisam de grande ventilação. Potência e velocidade: Motor potente de 200W. Hélices em plástico de engenharia: Além de fortes, são leves e aumentam a vida útil do motor. Oscilação horizontal: Proporciona um fluxo de ar melhor distribuído por todo o ambiente. Regulagem de Inclinação manual: Pode ser ajustada de acordo com a necessidade. Bivolt seletivo: Selecionar na chave seletora a seleção, 127V ou 220V. Pintura Eletrostática: Grade com pintura de alta resistência. Chave CVV: Acompanha chave de controle deslizante de velocidade. Disponível em 65cm', 449.0, 269.99, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3apj4ztbr2z78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F22298011440', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499546318', 'Filtro Óleo Peugeot 206 2005 a 2010 - 166919 - WOE710', 'Filtro Óleo Peugeot 206 2005 a 2010 166919 WOE710 (Feline / Holiday / Presence / Moonlight / Feline / Sensation) Motor 1.4 8v Gasolina / Flex - (Mecânico) - (Refil) (Com 1 oring)Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 37.94, 37.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd5b-m77cdc11uj61af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19499546318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
