INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20696892191', 'Lâmpada Led 1141 Ba15S Canbus Premium 1 Polo 12v 6000k Cambus Luz de ré Lanterna traseira e Seta Branca Fria Baixo consumo', 'TP-5058 - LÂMPADA LED1141 BA15S O top da qualidade máxima está com a Lâmpada Tarponn LED 1141 Ba15S Canbus Premium 1 Polo 12v 6000k! Modelo Premium, com um acabamento super refinado, possui aro de alumínio de alta potência na parte central do aparelho, funcionando como difusor de calor, além de ativar mais refrigerado, aumentando a sua vida. Além disso, possui 15 LEDS bem distribuídos, sendo 12 laterais e 3 frontais. Como é uma lâmpada de 1 Polo 1141, com a gestão Ba15S, pode ser instalada em luz de ré, lanterna traseira e seta. Para quem maior durabilidade, tecnologia, sofisticação e acabamento de alta qualidade, a Lâmpada Tarpon LED 1141 Ba15S Canbus Premium 1 Polo 12v 6000k é uma ótima opção. Escolha o melhor! CARACTERÍSTICAS • Dimensões do produto LxAxC: 1,6x4,5x1,6cm • Baixo consumo • Durabilidade superior • Iluminação branca fria • Fácil instalação • Aplicação: Luz de Ré, lanterna traseira e seta ESPECIFICAÇÕES • Cor: Branca Fria • Temperatura de Cor: 6000k • Encaixe: Ba15s • Tensão: 12v • Equivalência: 21w • Tipo de LED: SMD 3030 • Fluxo luminoso: 900 Im ITENS INCLUSOS • 1 Par de Lâmpada LED 1141 Ba15S Canbus Premium 1 Polo 12v 6000k', 49.99, 49.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7qvfv-lk8j1cpg8bsn5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413702429%2F20696892191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18345350281', 'Bota Galocha Dubuy Feminino Cano Alto Preto 1802FG', 'Além de práticas e ideais para dias frios, as galochas agora são também item Posh. Hoje em dia, além de figurarem em looks de diversos estilos, as galochas também ganharam novas versões, principalmente nos solados coloridos. Se você adora estar na moda, esta com certeza é uma peça ""must have"" para todas as estações de 2022. NUMERAÇÃO: 33 ao 40 MODELO: GALOCHA CORES: Preto, Areia, Branco MATERIAL EXTERNO: Ecológico MATERIAL INTERNO: Têxtil Espumado SOLADO: Borracha ratorado ESTILO PEÇA: Costurado PALMILHA: EVA ALTURA CANO: 38 cm ALTURA SALTO: 5 cm FECHAMENTO: Zíper Lateral Circunferência das Botas: 33/34 = 34cm 35/36 = 36cm 37/38 = 38cm 39/40 = 40cm "Receba sua compra no conforto da sua casa, comodidade e praticidade na hora de fazer compras" Tire todas suas dúvidas no campo de perguntas...', 189.99, 167.4, NULL, 'Women Shoes > Boots > Rain Boots', 'https://cf.shopee.com.br/file/35a6d617300a763f718ed3043c59cf85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842569660%2F18345350281', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
