INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44328938507', 'Prumo de Centro 600g com Cabo 5m MTX', 'O prumo de centro MTX é uma ferramenta prática para marcação e alinhamento em obras e instalações, oferecendo precisão e resistência. Com corpo de 600 g e cabo de 5 m, facilita transferir o ponto exato do teto ao piso com rapidez e estabilidade, ideal para profissionais da construção e DIY. Leve e compacto, seu formato permite manuseio simples e transporte fácil no canteiro de obras. O cabo longo de 5 m amplia o alcance sem perder controle, enquanto o peso de 600 g garante queda estável do prumo para marcações confiáveis. Características: Modelo: 848939 Referência: 848939 Produto: Prumo de centro Peso: 600 g Cabo: 5 m Marca: MTX EAN: 7899612751256 Benefícios: Permite marcações precisas do centro entre pisos e tetos. Fácil de manusear e transportar no canteiro de obras. Cabo de 5 m amplia o alcance de trabalho sem acessórios. Peso otimizado para queda estável e leitura rápida. Durável para uso contínuo em obras. Conteúdo da embalagem: 1 prumo de centro (600 g) com cabo de 5 m.', 45.04, 35.22, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260b-ml8kkcs51oncb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F44328938507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
