INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899433453', 'Escova Dental Classic Clean Colgate', 'A Escova Dental Colgate Classic Clean oferece uma higienização profunda e completa para sua higiene bucal diária. Suas principais características e benefícios incluem: * Cerdas macias para uma escovação delicada e confortável. * Design em "V" das cerdas, proporcionando maior alcance e limpeza entre os dentes. * Limpador de língua integrado para combater o mau hálito. * Cabo anti-derrapante para melhor manuseio durante a escovação. Dentistas recomendam a troca da escova a cada 3 meses ou conforme orientação do dentista. Após o uso, enxágue a escova, retire o excesso de água e coloque-a na posição vertical.', 14.99, 14.99, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-8259v-mqneku4thb7z65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554925%2F23899433453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
