INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697733890', 'Kit 24 Ceras Roll-on Refil Depilatória Clássica Mel Depimiel', 'Oii, é um prazer ter você aqui! Buscando uma depilação eficaz e prática? O Kit 24 Ceras Roll-on Refil Depilatória Clássica Mel Depimiel é a escolha perfeita para uma pele lisa e bem cuidada. O que é: - Kit com 24 Ceras Depilatórias Roll-on 100g; - Marca: Depimiel; - Não é Hidrossolúvel; - Para pelos mais resistentes; O que tem: - Mel; - Alta aderência; O que faz: - Hidrata; - Nutre; Área de uso: - Corporal; - Pelos normais; Como usar: 1- Aqueça o roll-on no aquecedor de cera roll-on. 2- Limpe a pele com a Loção Pré-Depilatória. 3- Destrave o roll-on passando-o sobre uma folha de Lenço Para Depilação. 4- Aplique a cera sobre a pele no sentido do crescimento do pelo. 5- Coloque o lenço para depilação sobre a cera e friccione-o. 6- Com uma das mãos puxe o lenço com firmeza e rapidez em sentido contrário ao crescimento do pelo (puxe sempre a folha paralelamente e tão próxima da pele quanto for possível). 7- Use o Óleo Removedor Hidratante para retirar os possíveis resíduos de cera e a Loção ou Gel Pós Depilatório Depimiel para atenuar a sensibilidade da pele. IMPORTANTE: - Não indicado aplicar em: Regiões Faciais: Buço, Barba, Nariz e Sobrancelhas. Regiões Íntimas Sensíveis. - Não é recomendado para gestantes, crianças, idosos, diabéticos ou após cirurgias. Não perca a chance de transformar sua rotina de depilação com um produto de qualidade. Garanta já o seu kit e sinta a diferença! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 249.98, 199.98, NULL, 'Beauty > Bath & Body Care > Hair Removal Cream & Wax', 'https://cf.shopee.com.br/file/sg-11134201-7reo3-m1sezsmnp809bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F22697733890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299631118', 'Meia Calça Natalina 7/8 Listrada Vermelha e Branca pra Fantasia Duende e Mamãe Noel', 'Itens inclusos: 01 Par de Meias 7/8 Dimensões do produto: Altura: 70 ~ 82 cm Largura: 10 ~ 19 cm Especificações Técnicas Material: :95% Poliéster e 5% Spandex. Cor: Vermelho e Branco. Produto: Novo, na embalagem. Produto a pronta entrega! Produto original! Transforme qualquer fantasia em algo especial com estas meias 7/8 listradas vermelha e branca, perfeitas para complementar fantasias natalinas ou cosplays. Feitas de poliéster e spandex, essas meias oferecem um tecido elástico, confortável e leve, que se adapta perfeitamente ao corpo. Com 70 cm de comprimento e 10 cm de largura, essas meias podem se esticar até 82 cm de comprimento e 19 cm de largura, garantindo um ajuste ideal para diferentes tamanhos. Use-as para criar um look incrível de Mamãe Noel, duendes de Natal ou qualquer outro personagem divertido. São práticas, estilosas e indispensáveis para quem quer caprichar nos detalhes da fantasia. Versatilidade: Mamãe Noel, duendes de Natal, elfos ou qualquer outro personagem divertido. Conforto: Tecido flexível que se ajusta bem às pernas. Estilo Clássico: Design simples e elegante. Alta Qualidade: Produzidas com material durável, ideal para várias utilizações.', 36.99, 36.99, NULL, 'Women Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-7rfg8-m44l27zciesw79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F18299631118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
