INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198443748', 'Jogo Bingo Completo 24 Cartelas + 90 Pedras Brinquedo Infantil Plástico Algazarra', 'Jogo Bingo Completo Com 24 Cartelas + 90 Pedras Plástico Algazarra Reúna a família e os amigos para momentos de pura emoção e sorte com o clássico Jogo Bingo Completo da Algazarra. Este kit vem com 24 cartelas e 90 pedrinhas, garantindo diversão para todos os envolvidos. Ideal para encontros familiares, festas e eventos comunitários, este jogo é um passatempo que atravessa gerações, promovendo laços afetivos e diversão inclusiva para todas as idades. Conteúdo do Jogo: - 24 Cartelas: Com design claro e numeração legível, permitindo que jogadores de todas as idades participem sem dificuldades. - 90 Pedrinhas Numéricas: Cobrem todos os números do jogo, assegurando que cada rodada seja única e emocionante. Características do Produto: - Completo e Pronto para Jogar: Tudo o que você precisa para iniciar um jogo está incluído neste kit. - Material de Qualidade: Produzido com materiais duráveis para resistir a inúmeras partidas. - Fácil de Armazenar: A embalagem é pensada para uma arrumação prática, facilitando a organização pós-jogo.', 41.9, 40.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8ouhokcw6iq09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314314958%2F22198443748', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
