INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40982638805', 'Calça Feminina Wide Leg Cintura Alta Pantalona Confortável Treino Academia Yoga', 'Esse é um produto da marca Livre do Brasil. Produto: Calça Feminina Wide Leg Cintura Alta Pantalona Suplex Nossa calça foi desenvolvida para quem busca conforto, estilo e versatilidade no dia a dia. Com modelagem ampla e caimento impecável, ela proporciona liberdade de movimentos e valoriza a silhueta, sendo perfeita para diversas ocasiões. Seu tecido é leve, macio e possui excelente elasticidade, garantindo um ajuste confortável ao corpo sem perder a elegância. A cintura alta oferece maior sustentação e um visual moderno, combinando facilmente com croppeds, camisetas, regatas e blusas. Ideal para o dia a dia, trabalho, viagens, passeios ou até mesmo para atividades leves. Cintura alta que modela o corpo Modelagem pantalona (pernas amplas) Fácil de combinar com diversos looks Disponível nos tamanhos: P / M / G / GG Postagem e envio: ENVIO IMEDIATO A Livre do Brasil é uma empresa brasileira. Temos todos os produtos em estoque. Assim que você faz o seu pedido, ele é conferido e embalado rapidamente, no prazo estipulado pela plataforma. O transporte é feito pela transportadora da plataforma que coleta os pedidos diretamente na nossa operação. O seu pedido é encaminhado ao centro de distribuição e segue de forma rápida e segura até você. Porque comprar os produtos da Marca Livre do Brasil: - Marca Brasileira. - Fabricação própria. - Preço justo e ótima qualidade. - Empresa com ótima reputação e excelentes avaliações. - Atendimento humanizado com honestidade e respeito.', 99.9, 49.98, NULL, 'Women Clothes > Pants & Leggings > Pants', 'https://cf.shopee.com.br/file/br-11134207-820mf-mqqfvpq1yarke0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F424871094%2F40982638805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43761910701', 'Caixa Térmica de 19 Litros Belfix Cor Preta com Marrom Tampa Removível com Porta Copos Integrado', 'O que está adquirindo: 1 Caixa Térmica 19 Litros Bel Onix (Ref. 071982) Descrição do Produto: A Caixa Térmica 19 Litros Bel é a aliada perfeita para quem valoriza conforto e praticidade durante momentos de lazer. Com excelente isolamento térmico em polietileno expandido (EPS), ela mantém suas bebidas geladas e alimentos frescos por horas, sendo ideal para praia, acampamentos, churrascos, viagens e encontros familiares. Seu design funcional conta com tampa com suporte para copos, alça ergonômica e trava de segurança, oferecendo mobilidade, conveniência e resistência em qualquer ambiente. Produzida com polipropileno 100% virgem, é atóxica, livre de BPA e fácil de higienizar. Características Principais: Isolamento térmico eficiente em EPS (Polietileno Expandido) Capacidade para até 12 garrafas PET de 600 ml ou 26 latinhas de 350 ml (sem gelo) Tampa com suporte para copos e trava de segurança integrada Alça ergonômica para transporte confortável Estrutura resistente, atóxica, livre de BPA e sem odores Fácil de limpar e ideal para uso frequente ao ar livre Especificações Técnicas: Marca: Bel Modelo: Caixa Térmica 19 Litros Onix – Ref. 071982 Capacidade: 12 garrafas de 600 ml ou 26 latinhas de 350 ml (sem gelo) Material: Polipropileno 100% virgem (livre de BPA) e EPS Cor: Preta / Marrom Dimensões Aproximadas (C x L x A): 38 cm x 26 cm x 32 cm Alças: Sim Porta Copos na Tampa: Sim Peso Aproximado: – Fabricado no Brasil: Sim Aplicações Recomendadas: Lazer em praias, campings e piscinas Eventos ao ar livre como churrascos e piqueniques Transporte de bebidas e alimentos com conservação térmica Atividades profissionais em campo que exigem refrigeração portátil Manuseio e Manutenção: Higienize a caixa com água e sabão neutro após o uso. Evite uso de objetos cortantes ou produtos abrasivos na superfície. Mantenha a tampa fechada para maximizar a eficiência térmica. Armazene em local seco, limpo e fora da exposição solar direta. SKU: 10010 Garantia: 3 meses de garantia contra defeitos de fabricação, conforme condições do fabricante Bel.', 99.99, 86.83, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-md4wc1bbxopafc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F43761910701', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
