INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17831333278', 'Creme para Pentear Redutor de Volume Brilho Máximo 1000g', 'Ele define, modela e ajuda na memorização dos cachos e crespos. Dá brilho, hidrata, controla o frizz e desembaraça os fios, tudo para que eles fiquem nutridos e com brilho. O creme é enriquecido com Óleo de Coco, Óleo de Amêndoas e Mel, que hidratam os fios de forma suave e sem agredi-los. O Creme para Pentear – Brilho Máximo, possui Óleo de Manga, Óleo de Argan e Colágeno. Indicado para cabelos cacheados, crespos ou volumosos. Efeito antifrizz, modelagem dos fios, hidratação e força, e reparação da fibra. Característica/Ação Possui Óleo de Manga, Óleo de Argan e Colágeno. Resultado Cachos definidos, com brilho e sem frizz', 69.0, 69.0, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7qownggzhvm6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F17831333278', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
