INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294071091', 'Jogo de Alicates para Abraçadeira de Mangueira Combustível óleo Lorben com 10 Peças + Maleta', 'O Conjunto de Alicates de Uso Profissional Lorben contém 7 diferentes estilos de alicates para as mais variadas aplicações automotivas. É ideal para a maioria das abraçadeiras de mangueira que equipam os veículos. Indicado para as mangueiras de combustível, óleo e água, ar condicionado, mangueiras radiais, para abraçadeiras de aço, entre outros. Marca: Lorben Material: Aço, PVC Cor predominante: Preto Inclui: Estojo para Armazenamento e Transporte 1 Alicate de abraçadeira elástica: 21x16x2,2cm 1 Rosca: 1,3x0,6x0,6cm 1 Alicate para abraçadeiras elásticas do radiador: 21x4,1x2,4cm 1 Alicate para abraçadeira com perfil chato: 21x4,5x2,4cm 1 Alicate com ângulo de 45°: 21x6,4x4,5cm 1 Alicate removedor de abraçadeira: 21x4,2x2,4cm 1 Alicate para abraçadeiras clic: 17x9,5x1,7cm 1 Alicate espaçador/removedor de mangueira: 20x9,6x2,2cm 1 Chave de Phillips: 15x1,7x1,7cm 1 Chave: 19x3,3x2,7cm Atenção: Cuidado durante o manuseio do produto para evitar acidentes. Mantenha longe do alcance de crianças. Tamanho da maleta: 45x27,5x9cm Peso da maleta com as ferramentas: 2,820kg Tamanho da embalagem: 47,5x37,5x11cm Peso da embalagem: 3,240kg Código do produto: GT6166 Imagens ilustrativas. As tonalidades podem variar.', 250.0, 250.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maec1uqixlh5b1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386114683%2F22294071091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40951981617', 'Porta Níquel Segredo Meigo Jacki Design Original com Alça – Compacto, Elegante e Seguro', 'O Porta Níquel Segredo Meigo da Jacki Design é perfeito para quem busca praticidade, organização e estilo no dia a dia. Com um design delicado e moderno, ele é ideal para guardar moedas, pequenos objetos, fones de ouvido, chaves ou outros itens essenciais com segurança. Fabricado com material de alta qualidade, possui acabamento resistente e fechamento seguro, garantindo durabilidade e proteção. Seu tamanho compacto facilita o transporte em bolsas maiores ou até mesmo usando a alça para carregar com mais praticidade. OBS: Os itens de conjunto irão com cores sortidos, não vai ser possível escolher as cores. Além de funcional, é um acessório charmoso que complementa seu visual com elegância. ✨ Características principais: Marca: Jacki Design Modelo: Segredo Meigo Tipo: Porta Níquel / Porta Moedas Material resistente e durável Fechamento seguro com zíper Design moderno e delicado Compacto e leve, fácil de transportar Ideal para moedas, fones, chaves e pequenos objetos Produto original Jacki Design 📏 Indicação de uso: Perfeito para uso diário, passeios, viagens, escola ou trabalho. Também é uma ótima opção de presente.', 14.9, 14.9, NULL, 'Women Bags > Wallets > Coin Holders & Purses', 'https://cf.shopee.com.br/file/br-11134207-81zte-mkwqt8xey5tsb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F530578890%2F40951981617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
