INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44559338016', 'Bota Feminina Couro Cano Alto Salto Alto Montaria Over The Knee Bottero Carrara 347805', 'Confeccionada em couro de alta qualidade, essa bota oferece durabilidade e estilo em cada passo. Seu acabamento em costura detalhada adiciona um toque de charme e qualidade ao calçado. Bota estilo "over the knee" ou acima dos joelhos. Confeccionada em couro legitimo com textura ravena en todo exterior do cabedal e cano Forro interno em tecido sintético para melhor conformto ao caminhar e facilidade para calçar. A parte da panturrilha conta com uma área de ajuste com forro em tecido elástico sintético e passadores para um cordão de couro de amarrar. Cano com 56 centímetros atrás medido a partir do chão 60 centímetros na parte da frente para cobrir os joelhos Circunferência de panturilha de 40 centímetros esticada sem aperto excessivo, o que seria justo mas ainda confortável Tornozelo com 28 centímetros Trilho interno de 23centímetros para ajudar os pés a passar pelo tornozelo Salto bloco com 6 centímetros Coleção Botnova Carrara XXIII (23) Produto ORIGINAL e com Garantia. **Após comprar, não esqueça de avaliar nosso produto e nosso atendimento, seu feedback é muito importante para nós, com ele temos como medir onde manter a qualidade e onde melhorar.**', 539.99, 499.99, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/br-11134207-820la-mnfud86ipfcw97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325939221%2F44559338016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
