INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23119827879', 'Barraca Camping 4 Lugares Iglu Luna Acapamento Sobreteto', 'Barraca Luna MOR – 4, 5, 6, 7 ou 8 Pessoas | Com Sobreteto e Bolsa de Transporte Ideal para quem busca conforto, proteção e praticidade ao acampar. As barracas Luna MOR são espaçosas, fáceis de montar e estão disponíveis nos tamanhos para 4, 5, 6, 7 ou 8 pessoas. Todas acompanham sobreteto com tratamento Silver Coating e proteção solar FPS 100, que reduz o calor interno e protege contra chuvas leves. Principais vantagens: Sobreteto com Silver Coating: ajuda a refletir o calor e proteger do sol Impermeabilização reforçada: até 800 mm ou 1200 mm de coluna d’água (conforme o modelo) Montagem fácil e rápida Tecido 100% poliéster e piso em polietileno Varetas de fibra de vidro leves e resistentes Bolsa para transporte incluída Mosquiteiro na porta, teto e janelas Gancho interno para lanterna ------------------------------------------------------------------------------------------------------------------------------ Tamanhos disponíveis: Luna 4 Pessoas Medidas: 2,10m x 2,10m x 1,30m (altura) Coluna d’água: 800 mm Medida na sacola: 60 x 20 x 20 cm ------------------------------------------------------------------------------------------------------------------------------ Luna 5 Pessoas Medidas: 2,40m x 2,40m x 1,30m (altura) Coluna d’água: 800 mm Medida na sacola: 60 x 18 x 16 cm ------------------------------------------------------------------------------------------------------------------------------ Luna 6 Pessoas Medidas: 2,60m x 2,60m x 1,65m (altura) Coluna d’água: 800 mm ------------------------------------------------------------------------------------------------------------------------------ Luna 7 Pessoas Medidas: 3,00m x 3,00m x 1,80m (altura) Coluna d’água: 800 mm Medida na sacola: 75 x 18 x 16 cm ------------------------------------------------------------------------------------------------------------------------------ Itens inclusos: 1 barraca Luna MOR (modelo conforme a seleção) 1 bolsa para transporte Envio rápido. Produto original com garantia de fábrica. Aproveite suas aventuras com mais conforto e segurança.', 389.9, 259.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mayarldfwl8vb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F415129379%2F23119827879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
