INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49652161132', 'Lovito Elegante Blusa Feminina de Primavera/Verão com Laço na Frente e Exquisita Cor Preta L158ED1583', '✅DESTAQUES -❤️Arco frontal -❤️Exótico -❤️trajeto -❤️Macio e confortável -❤️Primavera e verão ✅DESCRIÇÕES Estampa / Padrão:Plain Estilo:Elegante Tamanho Plus:Não Material:Poliéster Composição:95% Poliéster + 5% Elastano Tipo de modelagem:Ajuste Regular Transparência:Não Esticar:Sem elasticidade Feito na China ✅O PACOTE INCLUI 1XBlusa ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 59.29, 41.5, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134301-82272-mhj1h4k8osu8d5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F49652161132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598945029', 'Boia Inflável com Glitter Sort', 'Brilhe mais que o sol neste verão com a Boia Inflável com Glitter! Ela é transparente e com glitters coloridos, ideal para bons momentos na praia ou piscina. Com 80cm de diâmetro, suas medidas permitem a utilização por adultos e crianças. É produzida em vinil resistente, indicada para crianças acima de 3 anos e suporta até 45 Kg. Contém uma câmara de ar independente e uma válvula de segurança, acompanhando um adesivo para reparo que pode aumentar sua vida útil. Desinflada, torna-se fácil de transportar, podendo ser levada para qualquer lugar para garantir a diversão do verão!Atenção! Este não é um equipamento salva-vidas. Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto.', 50.0, 50.0, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824gv-mf8l9sdlkd1qaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23598945029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
