INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200160886', 'Boia Papagaio', 'Curtir o sol e a água fresca vai ser ainda mais divertido na companhia da Boia Papagaio. Com 2m de comprimento e 1,55m de altura ela é garantia de diversão pra toda a família. Produzida em vinil resistente, conta com três câmaras de ar independentes, três válvulas de segurança e acompanha adesivos de reparo. Com capacidade para até 90 Kg, possui duas alças para maior segurança e conta com assento central pra aproveitar com conforto os momentos na piscina ou praia. Peça já a sua e garanta lindas fotos nesse Verão! Atenção! Este não é um equipamento salva-vidas. Nunca deixe crianças sozinhas perto da água sem supervisão de um adulto. Item certificado pelo Inmetro.', 167.0, 99.0, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-8258s-mgfthcw87q4o80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F58200160886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198330795', 'Óculos de Natação Sport - Lilas', 'O Óculos de Natação infantil no modelo Sport da Mor possui lentes em poliestireno com PVC macio ao redor, para melhor ajuste e conforto para o rostinho dos pequenos. Sua tira regulável de borracha e regulagem entre as lentes também são confeccionadas em PVC. Disponível nas cores azul, lilás, rosa e verde com acabamento em amarelo, o Óculos Sport é o item que faltava para a criançada proteger os olhos durante as brincadeiras na água!', 7.0, 7.0, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Training Equipments', 'https://cf.shopee.com.br/file/sg-11134201-824j6-mfbbqsuqqxvuc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F20198330795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
