INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54214651700', 'Fones de Ouvido Esportivos Sem Fio SENBENBAO A520, Bluetooth 5.4, Estéreo, Gancho Ajustável, ANC, Microfone Integrado', 'Parâmetros do Produto: 1. Modelo: A520 2. Cores: Preto/Branco/Rosa/Cáqui/Verde/Azul 3. Versão: Versão 5.4 (emparelhamento automático) 4. Distância de Transmissão: 10–15 metros (linha reta ao ar livre) 5. Capacidade da Bateria: 60mAh por fone; 400mAh no estojo de carregamento 6. Tempo de Reprodução: 2–5 horas 7. Tempo de Conversação: 2–5 horas 8. Standby: 100 horas 9. Carregamento: 2 horas 10. Bluetooth: 5.4, baixo consumo de energia 11. Compatibilidade: Compatível com todos os dispositivos com Bluetooth Características: 1. Bluetooth 5.4, baixo consumo de energia 2. Ouça músicas e atenda chamadas 3. Fones de ouvido esquerdo e direito funcionam de forma independente 4. Reconexão automática ao ligar 5. Botões inteligentes: reproduzir/pausar, atender/desligar 6. Operação intuitiva: pressione e segure para ligar; toque único para controle Detalhes da Embalagem: • 1 par de fones de ouvido Bluetooth • 1 estojo de carregamento • 1 cabo de carregamento USB • Embalagem com bolsa de ar Observação: Para envios de longa distância, por favor, carregue primeiro. Para o primeiro uso, emparelhe completamente os fones de ouvido, depois conecte-os ao seu telefone. Se apenas um fone conectar, desconecte o Bluetooth no telefone, retorne ambos os fones ao estojo para reiniciar e emparelhe novamente.', 59.0, 58.9, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134253-82599-mqy0m6t7bhfm6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F54214651700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48414666968', 'Fones de ouvido sem fio Bluetooth LE302, fones de ouvido estéreo HiFi com cancelamento de ruído, ENC, à prova d''água e', 'Fones de Ouvido Bluetooth Lenovo LE302 Gamer – Baixa Latência HD e Chip Personalizado Alimentados por um chip gamer personalizado, esses fones de ouvido proporcionam uma latência ultra-baixa de 0,03s para uma experiência mais imersiva. O Bluetooth 6.0 garante uma conexão estável e sem interrupções, com alcance de 15m. Chamadas Nítidas e Controle por Toque Desfrute de chamadas binaurais em alta definição e com microfone integrado para chamadas mãos-livres. Os controles por toque populares permitem trocar de faixa e ativar o Siri facilmente. Diversão o Dia Todo Uma única carga fornece até 4 horas de reprodução; o estojo de carregamento oferece 3 a 4 recargas extras para um total de 30 horas — o suficiente para uma semana inteira de uso. O modo de espera dura cerca de 1 semana. Compatibilidade Universal Funciona com qualquer dispositivo compatível com Bluetooth, oferecendo ampla compatibilidade. Design Confortável de Gancho de Orelha O design ergonômico do gancho de orelha garante um ajuste seguro e confortável para longas sessões de audição. Resistente e Durável Resistência à água IPX5 e proteção contra poeira IP5X mantêm seus fones seguros durante treinos e uso diário. Áudio Estéreo Duplo Ambos os fones oferecem áudio estéreo verdadeiro sem fio para um som espacial equilibrado. Especificações do Produto - Marca: Lenovo - Modelo: LE302 - Bluetooth: 6.0 - Cores: Preto, Branco, Roxo, Rosa, Verde - Material: Plástico - Resistente à água: IPX5 - Resistente à poeira: IP5X - Duração da bateria: 4h (fones) + 30h totais com o estojo - Carregamento: Estojo de carregamento incluso Conteúdo da Caixa - 1 par de fones de ouvido - 1 estojo de carregamento - 1 cabo de carregamento - 1 manual do usuário (chinês/inglês) Configuração Inicial Após retirar os fones do estojo de carregamento, ambos ligarão e parearão automaticamente (LED principal aceso, secundário apagado). Para o primeiro uso, conecte manualmente via Bluetooth; conexões futuras são automáticas ao retirá-los do estojo. #Lenovo #LE302 #SemFio #FonesDeOuvidoBluetooth #BaixaLatência #HeadsetsGamer #BateriaDuradoura #CompatibilidadeUniversal #ControlePorToque #ChamadasBinaurais #ResistenteÀÁguaIPX5', 101.4, 78.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134253-82593-mqxwtbb9hedgd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F48414666968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
