INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255442324', 'Fatiador Tupperware Super Chef Mini', 'O Super Chef Mini é um fatiador que todo mundo precisa na cozinha! Rápido, compacto e multifuncional, pode ser usado com ingredientes pequenos, como nozes e vegetais de forma segura graças ao protetor para os dedos. A lâmina com corte em ambos os lados agiliza o processamento do alimento. Use-o para todos os tipos de pratos - Desde a entrada até as sobremesas, para finalizar ou preparar prato. Quando não estiver em uso deixe o protetor na posição "cadeado". SOMOS A LOJA OFICIAL DA TUPPERWARE: TODOS OS NOSSOS PRODUTOS SÃO ORIGINAIS E VÊM DIRETO DA NOSSA FÁBRICA PARA O CONFORTO DO SEU LAR.', 253.29, 189.9, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/br-11134207-820mc-mmw0psu52bk0d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1608053305%2F58255442324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094790893', 'Café Torrado e Moído Sul de Minas Gourmet 3 Corações', 'O Café Gourmet 3 Corações Sul de Minas é um convite aos apaixonados por café, oferecendo uma experiência única a cada xícara. Com grãos 100% arábica plantados nas regiões cafeeiras mais nobres do Brasil, este café torrado e moído proporciona sabores e aromas diferenciados. * Sabor: notas de castanha e amêndoas. * Aroma: intenso de frutas secas. * Acidez: média cítrica. Modo de Preparo: Use 5 a 6 colheres de sopa de café cheias para cada litro de água quente. Adoce somente na hora de servir. Para preservar o aroma e o sabor, guarde o pacote em um recipiente fechado.', 35.99, 25.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-8258n-mqnem3llnfnld7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302953%2F22094790893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698566004', 'Kit Pantene Equilíbrio Shampoo 300ml + Condicionador 150ml + Creme Para Pentear 240g', 'O Kit Pantene Equilíbrio Shampoo 300ml + Condicionador 150ml + Creme Para Pentear 240g combina limpeza eficaz com hidratação leve, ideal para cabelos mistos oleosos na raiz e secos nas pontas. Sua fórmula exclusiva, com Pro-Vitaminas e extratos naturais, remove impurezas e oleosidade excessiva sem agredir os fios, restaurando o equilíbrio natural do couro cabeludo e proporcionando maciez e movimento aos cabelos. Benefícios:Equilíbrio perfeito entre limpeza e hidratação.Remove a oleosidade sem ressecar.Hidratação leve e controle do frizz.Fios mais macios, soltos e com movimento natural.Creme para pentear com proteção térmica e toque leve.Ideal para cabelos mistos e uso diário. Modo de usar:Shampoo: Aplique nos cabelos molhados e massageie suavemente o couro cabeludo. Enxágue.Condicionador: Aplique no comprimento e pontas, deixe agir por alguns minutos e enxágue.Máscara Capilar: Aplique a máscara nos fios úmidos, deixe agir por 3 a 5 minutos e enxágue. Sobre a marca: Presente no mercado global há mais de 40 anos, Elseve, marca da L''Oréal Paris, é sinônimo de inovação em tratamento capilar. Seus produtos são desenvolvidos com tecnologia de ponta e ingredientes poderosos para oferecer soluções eficazes para todos os tipos de cabelo. Com linhas icônicas e resultados comprovados, Elseve combina ciência e beleza para revelar o melhor dos seus fios em cada aplicação.', 64.77, 53.74, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260q-ml26gnsapr7lf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22698566004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598539094', 'Ar Condicionado Split Cassete Inverter TCL 36000 BTU/h 4 Vias Frio TAC36CSGCTINV – 220 Volts', 'Ar Condicionado Split Cassete Inverter TCL 36000 BTUh 4 Vias Frio TAC36CSGCTINV – 220 Volts O Ar Condicionado Split Cassete Inverter TCL 36000 BTUh Frio TAC36CSGCTINV é a escolha ideal para ambientes comerciais e residenciais que precisam de conforto térmico eficiente e discreto. Este modelo combina alta capacidade de resfriamento com tecnologias de economia de energia, sendo ideal para espaços de médio a grande porte Características Principais : Alta EficiênciaEnergética: Equipado com tecnologia inverter e gás ecológico R32, que proporciona um funcionamento mais econômico e reduzido impacto ambiental Distribuição Uniforme do Ar: A instalação no teto permite que o ar seja distribuído de maneira uniforme em todo o ambiente, com fluxo de ar em 360°, garantindoconforto em todos os cantos do espaço. Operação Silenciosa: Projetado para oferecer um funcionamento silencioso, perfeito para locais que exigem um ambiente tranquilo, como escritórios e salas de reunião. Design Compacto e Discreto: O design cassete permite que a unidade se integre facilmente ao teto, otimizando o espaço e mantendo a estética do ambiente. Controle Avançado: Vem com um controle remoto multifuncional, facilitando a operação e o ajuste da temperatura conforme necessário. Durabilidade e Facilidade de Manutenção: Desenvolvido para resistir ao uso intensivo, com materiais de alta qualidade e fácil acesso para manutenção. Imagens meramente ilustrativas.', 10301.0, 10301.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-8257w-mqlzzw308w0df9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1323031590%2F22598539094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198567623', 'VERNIZ ALTO SOLIDO PU BI 4800 2:1 AS + END 0,9L DUXONE', 'Descrição: Verniz bi componente à base de resina acrílica reticulada com isocianato alifático. Indicada para pintura geral ou retoque, formando um sistema dupla camada com Duxone Base Poliéster. Relação Mistura: Para 2 partes de DX4800 adicionar 1 parte de catalisador DX0148 e ou DX0149. Diluir de 10 a 20% com DX7000 Ajuste Aplicação: Pistola Convencional: - Bico: 1.4 mm - Pressão: 40 – 50 lbf/in² / Pistola HVLP: - Bico: 1.4 – 1.6 mm - Pressão: 6 – 8 lbf/in² Aplicação:Aplicar 2 demãos. Intervalo Demãos: Aguardar 5 a 10 minutos entre demãos. Secagem: Ao Ar Normal: - Toque: 3 a 5 horas - Polimento: 24 horas Ao Ar Acelerado: - Toque: 1 a 3 horas - Polimento: 12 horas Estufa: - Flash-off: 20 minutos - Ciclo: 30 minutos @ 60ºC Rendimento: 7 - 8 m2 /litros para 2 demãos. VERNIZ ALTO SOLIDO PU BI 4800 2:1 AS + END 0,9L DUXONE', 143.42, 143.42, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7ravc-man07ruwwo0g8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343260914%2F23198567623', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
