INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297739926', 'Kit Cronograma Antifrizz Para Tratamento Dos Fios Hidratei', 'Diga adeus ao frizz para sempre. Sabemos que muitas mulheres sofrem com os fios arrepiados e rebeldes, mas agora você vai assumir o controle absoluto dos seus cabelos. Com a linha Antifrizz da Hidratei, seus cabelos ficarão mais alinhados e disciplinados desde a primeira lavagem. Nossa equipe desenvolveu essa linha completa com ativos cuidadosamente selecionados para proporcionar resultados incríveis, sem ressecar os fios. Benefícios: - Proteção Térmica até 230°c - Elimina o frizz sem sacrificar a saúde capilar - Proteção Contra a Umidade - Efeito Liso perfeito sem alisantes', 563.5, 390.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mctcytcw9ohe64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F555452587%2F19297739926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899333754', 'Alarme Universa Automotivo Carro Pósitron Cyber Exact Ex360', 'Alarme Automotivo Pósitron EX360 Cyber Exact Universal Desenvolvido no modelo Exact 360 da linha 2017, este Alarme para Carro apresenta diversas funções que trarão muito mais praticidade e segurança ao seu dia a dia no carro, como a função Controle de Som e Acionamento dos Faróis. O Pósitron EX360 vai completo e prontinho para instalar, acompanha dois controles bem compactos com sistema anti clonagem e com LEDs indicadores na cor vermelha. Além disso, apresenta a tecnologia PAN, que permite que o Alarme seja compatível com outros produtos da linha Pósitron. Praticidade e proteção é com a Pósitron! Especificações Gerais: • Modelo Exact 360 • Acompanha 2 Controles PXN62 • Controles Remotos com Sistema Pósitron Anticlonagem New Flex-Code 3 • Aplicação Universal • Modo Assalto Passivo por Porta Ignição: Bloqueio Progressivo do Motor de Partida ou Bomba de combustível, quando a Ignição for ligada e/ou a Porta do Veículo for aberta sem pressionar o Botão Secreto • Controle de Som: Liga e Desliga o Som pelo Alarme • Função Pânico: Pressionando o Botão Liga do Controle Remoto por 5 Segundos • Cancelamento Temporário do Sensor de Ultrassom • Pisca Setas e Função Acendimento dos Faróis • Trava Automática “Autolock”: Função que Possibilita o Travamento das Portas em 5 Segundos após a Ignição ter sido Ligada e Destrava as Portas ao Desligar a Ignição • Luz de Aproximação • Módulo com Exclusiva Tecnologia ASIC: Circuito Integrado que torna o Módulo mais resistente às Interferências Eletromagnéticas e evita Disparos Falsos • Exclusivo Controle Remoto com Tecnologia ASIC: Compatível com Qualquer Bateria do Mercado • 1 Saída Auxiliar que Possibilita a Descida dos Vidros Elétricos (Inclusive 0riginais) ou Abertura do Porta-malas • Exclusiva Tecnologia PAN (Pósitron Area Network), que permite que o Alarme seja compatível com outros Produtos da Linha Pósitron • Gravação de Até 4 Controles Remotos • Sirene com Volume de Som mais alto, mas que atende às normas do Contran • Disparo do Alarme em Caso de retirada as Cápsulas Receptoras de Ultrassom • Permite comandar as Travas Elétricas do veículo por Controle Remoto • Permite Cancelar o Beep ao Ativar e Desativar o Alarme pelo Controle • Reativa Automaticamente o Alarme ao Desativá-lo caso Ninguém entre no Veículo • Beep Personalizado ao Ativar e Desativar o Alarme (6 opções diferentes) • Possibilidade de Monitorar o Interior do Veículo através do Ultrassom com LED Externo e Interno • Função que Permite acionar o Portão Eletrônico Conteúdo Da Embalagem • 02 Controles • 01 Módulo • 01 Sirene • 01 Chicote • 01 Kit de Instalação • 01 Manual de Instruções', 500.0, 289.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkih5xwy6rr4d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F23899333754', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
