INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597699523', 'Bancada Cozinha Americana Gourmet com Prateleiras', 'Com design clean e minimalista, a Bancada Linha Home NetMobil se adapta perfeitamente à sua casa, seja na cozinha, área de lazer ou integração de ambientes. Fabricada em MDP de alta qualidade e acabamento impecável em ABS, garante resistência, durabilidade e um visual moderno e sofisticado. Funcionalidade e Elegância em Perfeita Harmonia: Espaço amplo para cozinhar e preparar alimentos: A bancada oferece uma superfície espaçosa para você preparar suas refeições com conforto e praticidade. Prateleiras fixas para organização: Utilize as prateleiras para organizar seus utensílios, temperos e outros itens de cozinha, mantendo tudo à mão. Vãos internos para eletrodomésticos: Guarde seus eletrodomésticos pequenos nos vãos internos da bancada, otimizando o espaço em sua cozinha. Estilo: Clássico Peso (kg): 30 Garantia: 03 Meses Altura (cm): 96 Acabamento: BP Melamínico Largura (cm): 140 Possui Pés: Não Possui Portas: Não Suporta Até (kg): 20 Acompanha Tampo: Sim Profundidade (cm): 50 Escala de Brilho: Fosco Serviço Montagem: 114259443 Material do Tampo: MDP Origem do Produto: Nacional Ambiente Principal: Escritório Material Principal: MDP Sapatas Niveladoras: Sim Material da Prateleira: MDP Acabamento da Prateleira: BP Melamínico Peso Máximo por Prateleira: 20 Escala de Brilho da Prateleira: Fosco Marca: Netmobil Cor Interna: Preto Cor do Produto: Nogal Itens Inclusos: 1 Bancada Cozinha, manual de montagem e kit ferragens. Cor Predominante: Marrom Linha ou Coleção: Home Medida do Tampo (L x C x E): 140x60x3', 484.62, 484.62, NULL, 'Home & Living > Kitchenware > Kitchen Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rdwe-lyd1cr4zkpcyf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduc