INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297982407', 'Boneco Funko Pop! One Piece - Luffy com Carne', 'Aumente sua coleção com o Boneco Funko Pop! Luffy com Carne! Monkey D. Luffy, o destemido capitão dos Chapéus de Palha, está pronto para liderar sua tripulação com um pedaço de carne em mãos. Este detalhado Boneco Funko Pop! captura a essência do icônico personagem de One Piece, ideal para fãs da série. A figura de vinil tem aproximadamente 11 centímetros de altura e é um acréscimo imperdível para qualquer coleção dedicada ao anime.', 164.99, 164.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rfhz-m32dv3kyxkjd6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F21297982407', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
