INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27241444558', 'Conjunto de Roupa Our Generation Maiô e Acessórios', 'Prepare a sua boneca Our Generation para dias de sol e aventuras à beira da piscina com o Conjunto de Roupa Maiô e Acessórios! Este conjunto exclusivo para bonecas de 46 cm traz um maiô rosa com detalhes delicados em babados, combinando perfeitamente com a parte de baixo estilosa e o colete salva-vidas com estampa colorida de corações, garantindo diversão e segurança nas brincadeiras imaginativas. Completo com óculos de natação e sapatos transparentes para água, o conjunto oferece um visual moderno e pronto para mergulhar em histórias cheias de criatividade e aventura. Compatível com a maioria das bonecas Our Generation de 46 cm e seus acessórios, este kit é perfeito para quem deseja expandir o guarda-roupa da boneca com estilo e versatilidade. O Conjunto de Roupa Our Generation Maiô e Acessórios é a escolha certa para transformar cada dia em uma verdadeira festa na piscina!', 279.99, 279.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-824ho-mekfomx4wb2e4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F27241444558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
