INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498751134', 'Pedivela Single GTS 34D 1 x 12v 170mm Ponta Quadrada Coroa Fixa GTS Pro 34 Dentes', 'Pedivela GTS Single 34D – Alumínio 170mm | Para Fixie, Single Speed e Urbanas Leveza, estilo e eficiência em cada pedalada! O Pedivela GTS Single 34 dentes é perfeito para quem pedala na cidade, usa bike fixa ou curte o visual clean do single speed. Com coroa integrada de 34 dentes, braços de 170mm e estrutura em alumínio de alta resistência, ele garante mais agilidade, durabilidade e uma transmissão suave no dia a dia. Especificações Técnicas: • Modelo: Single Speed com coroa integrada de 34 dentes • Comprimento dos braços: 170mm • Material: Alumínio leve e resistente • Acabamento: Preto fosco com logo GTS • Design da coroa: 4 recortes triangulares – mais leveza sem perder rigidez • Compatibilidade: Bicicletas urbanas, fixas (fixie), single speed • Movimento central compatível: 34.7mm ponta quadrada • Incluso no kit: ️ 2 braços do pedivela ️ 1 coroa integrada ️ 2 tampas de acabamento ‍️ Benefícios: • Ideal para uso urbano, fixies e projetos personalizados • Transmissão direta e eficiente – resposta rápida no pedal • Estilo moderno com acabamento premium • Fácil de instalar e compatível com diversas bikes • Excelente custo-benefício para quem busca performance sem complicação Produto novo | Envio rápido | Qualidade GTS Perfeito para quem pedala na cidade com estilo e exige confiança em cada peça!', 86.03, 86.03, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdw3-mcm4uxx0bpgza4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22498751134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14822579004', 'Espátulas para pneu bicicleta Park Tool TL-4.2 PARA TIRAR PNEU SPEED MTB TT', 'A Espátula Park Tool TL-4.2 foi desenvolvida para auxiliar os ciclistas na troca dos pneus, tem o design ergonômico que facilita a empunhadura para uso e desenho que facilita a entrada e fixação junto aos pneus e aros da bicicletas para maior praticidade e eficiência, sem causar riscos e com melhore encaixe para a remoção, mesmo em pneus com bordas mais finas ou em pneus e rodas com sistemas tubeless. A extremidade com sistema de fixação duplo para a colocação nos raios garante ainda mais praticidade para a remoção com segurança e muito mais qualidade em um sistema de fabricação plástica de maior resistência para mais durabilidade. Especificações: - Ponta voltada para maior facilidade - facilita o encaixe junto aos aros e pneus inclusive de sistemas tubeless; - Fabricação em plástico de alta resistência - muito mais durabilidade e facilidade na hora do uso; - Ponta dupla para fixação nos raios - facilidade para maior encaixe e ajuda na retirada dos pneus; - Medidas aproximadas: Comprimento 11 X 2,5 Largura (medidas em cm).', 29.9, 29.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg3tmottze9w84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F14822579004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
