INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399889698', 'Sandália Tanara Rasteira Feminina T9341', 'Produto marca Tanara. A Sandália Tanara Rasteira é a combinação perfeita entre conforto e brilho. Com um design minimalista e bico quadrado, ela se destaca pelas tiras finas adornadas com aplicações de brilho, que elevam qualquer look com um toque de glamour. o fechamento por fivela no tornozelo garante um ajuste seguro e prático, ideal para a mulher que busca estilo e versatilidade para o dia a dia. Mais do que um calçado, esta sandália é um convite para desfrutar da leveza, com 0,546 kg, e da beleza em cada passo. Perfeita para momentos de lazer e para dar um toque especial às suas produções, a sandália rasteira com 1 cm é um item indispensável no seu guarda-roupa de verão. o material sintético de alta qualidade garante durabilidade e conforto prolongado, permitindo que você caminhe com confiança e elegância. Sinta o poder do brilho e da sofisticação com a Sandália Rasteira Tanara. Adquira agora e transforme seus looks com um calçado que une conforto, design exclusivo e elegância. Peso: 0,546 kg Altura da sola: 1,00 cm', 229.9, 219.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-824jb-me7n1yxzkdflff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F18399889698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
