INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498157834', 'Kit 2x Óleo De Prímula 400mg Total 120 Caps - 2 Meses Bodyaction', 'ÓLEO DE PRÍMULA INGREDIENTES: Óleo de primula. INGREDIENTES DA CÁPSULA: Gelatina, água purificada e umectante glicerina. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Ingerir 02 (duas) cápsulas por via oral ao dia do suplemento alimentar. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: "MANTENHA FORA DO ALCANCE DE CRIANÇAS." *ESTE PRODUTO NÃO É UM MEDICAMENTO.'' "NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM". CONSERVAÇÃO: Manter em sua embalagem original, em temperatura ambiente. Proteger da luz e manter em lugar seco. Preservar a integridade da embalagem. Depois de aberto, consumir preferencialmente em 30 dias.', 187.38, 129.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5d2eolv1ids21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024736570%2F22498157834', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
