INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17393721754', 'Jogo Rummikub - Grow', 'Jogo Rummikub - GrowO Jogo Rummikub - Grow é um dos mais populares em todo o mundo e foi trazido com exclusividade para o Brasil pela Grow. Com um campeonato mundial realizado a cada 3 anos, este jogo desafia os jogadores a se livrarem de suas 14 pedras inicialmente distribuídas, baixando jogos sobre a mesa. O grande diferencial deste jogo está na possibilidade de "encaixar" suas pedras nos jogos baixados pelos oponentes, proporcionando uma gama infinita de estratégias e possibilidades para vencer. Com atenção, raciocínio e um toque de ousadia, jogadas surpreendentes estão sempre à espreita, tornando cada partida única e emocionante. Idade recomendada: A partir de 7 anos. Selo Inmetro: CE-BRI/ICEPEX-N 01264-25 - NM300-2004 OCP 0046. Mais sobre o Produto:Jogo Rummikub da Grow, ideal para meninas e meninos de 7 a mais de 14 anos que gostam de desafiar, estimulando o raciocínio lógico, a concentração e a interação social por meio de combinações estratégicas, em uma embalagem prática e compacta. Dicas de Uso:Para se destacar no Jogo Rummikub - Grow, é importante observar atentamente as jogadas dos adversários, identificar oportunidades para encaixar suas pedras nos jogos existentes e criar sequências criativas para se desfazer das pedras o mais rápido possível. Lembre-se de que a chave para o sucesso está na combinação de estratégia e astúcia. Ficha Técnica:Marca: Grow; Nome do produto: Jogo Rummikub; Idade recomendada: A partir de 7 anos; Selo Inmetro: CE-BRI/ICEPEX-N 01264-25 - NM300-2004 OCP 0046; Contém: 104 pedras numeradas, 2 pedras-curinga, 4 suportes plásticos e 1 manual de instruções.', 305.99, 305.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-8260a-ml5iypn9uayp71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F17393721754', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19533966887', 'Essência Lavanda Via Aroma - 10ml', 'Essências Linha Clássica Via Aroma - 10ml- Para Aromatizador Difusor ElétricoAs Essências da Linha Clássica Via Aroma são cheirinhos de casa disponíveis nas mais diversas fragrâncias para você escolher. Nossa maior coleção de aromas composta por perfumes de ambiente para você usar no Aromatizador Elétrico. Inspire-se com aromas florais incríveis, cítricos refrescantes e amadeirado intensos para deixar toda a casa cheirosa. Confira as opções disponíveis e escolha suas favoritas.MODO DE USARNo Aromatizador Elétrico Via Aroma, adicione 15 gotas da Essência, conecte na tomada e curta o aroma.PRECAUÇÕESManter fora do alcance de crianças e animais domésticos. Uso externo. Não ingerir. Evite contato prolongado com a pele. Inflamável, deixe longe do fogo e superfícies aquecidas. Em contato com a luz, pode haver alteração de cor. Armazene em local ventilado e protegido da luz. Em caso de sensibilização, busque atendimento médico.', 20.99, 19.94, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Essential Oils', 'https://cf.shopee.com.br/file/sg-11134201-81zw4-mmrt1fvxfqbq80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545693995%2F19533966887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
