INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197784306', 'Kit 2 Pares Meia Masculina Feminina Poliamida Esporte Ciclismo Corrida Cano Alto Performance Fitness', 'O Kit Meia Cano Alto Masculina é a escolha ideal para quem busca superar seus limites com estilo e conforto. Produzidas com materiais de alta qualidade, essas meias garantem durabilidade, ajuste perfeito e suporte adicional durante suas atividades esportivas. Com um design moderno e funcional, as meias de performance proporcionam o suporte necessário para manter os pés secos e confortáveis durante treinos intensos. Disponíveis em opções de estampas exclusivas, as meias do Kit Meia Cano Alto Masculina são 100% fabricadas no Brasil pela Winston, uma marca com 56 anos de história e reconhecida por sua qualidade superior. Se você valoriza o desempenho aliado ao estilo, este kit é a escolha perfeita para treinos ao ar livre, na academia, ou em qualquer outra prática esportiva. Invista no conforto e na tradição de quem entende de meias! Composição: • Poliamida (97%): Oferece resistência, secagem rápida e um toque suave para a pele. • Elastano (3%): Proporciona elasticidade para um ajuste firme e confortável, adaptando-se perfeitamente aos pés.', 63.99, 52.99, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhvyip1ztx4xda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920749716%2F21197784306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
