INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799308985', 'Princesas Disney 1x Boneca Articulada 38cm - Multikids', 'Para toda menina que sonha com aventura, há uma Princesa Disney para mostrar que é possível. Uma Princesa Disney é alguém que acredita em si mesma, nunca desiste e exibe coragem ao explorar mundos novos e emocionantes. Ela é um exemplo para todas as meninas serem honestas, gentis, curiosas, demonstrarem preocupação com os outros e como ser uma boa amiga. Uma Princesa Disney que segue seu coração sabe que possui a coragem para realizar seus sonhos e que aventuras a aguardam! Compartilhe aventuras eternas e cotidianas com uma amiga querida tanto debaixo do mar quanto em terra firme com a linda Boneca Disney Princess Ariel! Característica do Produto: - Largura do produto 11cm - Altura aprox. do produto: 38cm - Peso aprox. do produto: 500g - Faixa etária: +3 anos - Comprimento do produto: 16cm - Composição do Material: Plástico, Poliéster - Desenvolvimento: Cognitivo, Motor - Sem som Conteúdo de Embalagem: - 1x Boneca Princesas Disney Articulada. Características: Marca:Multikids *Imagens Meramente Ilustrativas', 289.32, 256.63, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdvd-lye0ow1nb3jr69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F19799308985', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
