INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18498353393', 'Kit Bebida Vegetal NotCo NotMilk Semi Desnatado 1L', 'Descubra o sabor e versatilidade do Leite Vegetal NotCo NotMilk Semi Desnatado 1L. Feito com ingredientes 100% vegetais, esse leite vegano é uma opção deliciosa e saudável para substituir o leite convencional. Fonte de cálcio e vitaminas essenciais para o seu dia-a-dia. Cremoso e com sabor suave, é perfeito para beber puro, adicionar a receitas ou preparar seus smoothies, vitaminas, cafés e chás preferidos. Com baixo teor de gordura, é perfeito para quem busca uma opção equilibrada e para quem se preocupa com a saúde. É a escolha perfeita para pessoas com restrições alimentares: sem lácteos, sem lactose, sem glúten, sem colesterol. Experimente agora e se surpreenda!', 107.94, 102.54, NULL, 'Food & Beverages > Beverages > Non-dairy Milk', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfow57zrfchsb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1567163664%2F18498353393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
