INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893788327', 'Jogo De Pratos Fundos 28cm Kit 4 Peças Sienna Sopa Porcelana Borda Decorada Tramontina', 'Kit 4 Pratos Fundos Tramontina Sienna Porcelana – Sofisticação e Versatilidade para a Sua Mesa O Kit com 4 Pratos Fundos Tramontina Sienna é a escolha perfeita para quem busca aliar elegância e praticidade ao servir sopas, caldos e massas. Com design contemporâneo e acabamento de alta qualidade, essas peças adicionam um toque de sofisticação à sua mesa, tanto no dia a dia quanto em ocasiões especiais. Fabricados em porcelana resistente e durável, os pratos oferecem excelente desempenho térmico, são compatíveis com micro-ondas e lava-louças, e possuem superfície lisa, facilitando a higienização. Seu formato profundo valoriza a apresentação dos alimentos, tornando cada refeição mais elegante. Características: Kit com 4 pratos fundos Design moderno e minimalista Porcelana de alta resistência e durabilidade Compatíveis com micro-ondas e lava-louças Superfície lisa e fácil de higienizar Ideal para uso doméstico ou profissional Perfeito para quem valoriza qualidade, bom gosto e funcionalidade na composição da mesa.', 169.9, 169.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-824hv-mfb4ozwuu4gcf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F23893788327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
