INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094744238', 'Rack Charlotte MDF com Pés 2 Portas Artely', 'Se você busca um móvel para apoio da TV e para deixar seu ambiente ainda mais lindo, você precisa conhecer o Rack Artely 2 Portas Charlotte. Ele é a inspiração e aconchego que todo lar deveria ter. Cria um composição elegante e deixa a sua sala de TV moderna e agradável. O Rack possui pés de MDF 25mm, nichos e 2 portas de abrir com dobradiça de metal. Com pintura UV texturizada, sua manutenção fica muito mais fácil. Além disso, o móvel possui três meses de garantia. A responsabilidade com meio ambiente também é uma das bandeiras da Artely Móveis. Não perca essa oportunidade e garanta já o seu! Características do Produto: Marca: Artely Modelo: Charlotte Matéria-prima: MDF 25 mm Revestimento: UV Acabamento: Fosco Portas: 2 Dobradiças: Metálicas Puxadores: Plásticos Prateleiras: 01 prateleira Capacidade de carga: 20 Sistema de montagem: Minifix, cavilhas e parafusos. Pés: 5, MDF 25 mm Altura dos pés: 18 cm Dimensões do Produto: Altura: 55 cm Largura: 180 cm Profundidade: 40 cm Dimensões Máximas da TV: Altura: 40 cm Largura: 180 cm Garantia do Fabricante: 3 meses Observações: As cores apresentadas podem sofrer variações de tonalidade de acordo com o visor utilizado para visualização do produto em relação ao produto físico.', 420.19, 420.19, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-8225x-mhksb5annz0lfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630032069%2F22094744238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201025537', 'Fogão a Gás CFO4ZAB 4 Bocas com Mesa Esmaltada, Branco Consul', 'O novo Fogão a Gás Consul 4 Bocas com Mesa Esmaltada, Branco CFO4ZAB combina praticidade e design. A mesa esmaltada é fácil de limpar e ajuda a evitar riscos, mantendo o produto com aparência de novo por mais tempo. Com forno de 58 Litros  o maior do segmento  você tem mais espaço para preparar receitas, além de ter chamas bem distribuídas que garantem assados mais uniformes. As grades duplas de arame redondo são até 3x mais resistentes e oferecem mais firmeza, mesmo com panelas pesadas. Os pés elevados facilitam a limpeza do chão, sem precisar mover o fogão. Não perca essa oportunidade e garanta já o seu! Modelo: CFO4ZAB Tipo: A gás Tipo de fogão Piso Tipo de gás: GLP ou GN Cor: Branco Bocas: 04 Entrada do gás: Lado direito visto de frente Acendimento: Automático Potência dos queimadores; Queimador rápido: 2750 W | Queimadores semirrápidos: 1650 W Mesa; Esmaltada Botões: Removíveis Trempes: Duplas de arame redondo Capacidade do forno: 58 litros Temperatura máxima do forno: 280ºC Temperatura mínima do forno: 160ºC Sistema de segurança corta gás: Sim Quantidade de prateleiras: 1 Plugue e tomada: 10 A Puxadores: Plástico de engenharia Pés: Elevados Vidro interno vedado: Sim Classificação Energética: A Voltagem: Bivolt Conteúdo da embalagem: 1 Fogão, 1 Kit com manual de montagem, pés frontais e traseiros Peso; 20,10 kg Largura: 51,40 cm Altura: 88,50 cm Profundidade: 60,30 cm Garantia: 1 ano Marca: Consul', 955.07, 955.07, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-82283-mhhziryxsiyq53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630032069%2F58201025537', NULL, NULL, '2026-07-28T02:11: