INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598954339', 'CORTADOR KIT RÉGUAS MINIATURAS 5 FLORES - 3 PEÇAS (BLUE STAR) (CHOCO)', 'Cortador Kit Réguas Miniaturas 5 FLORES - 3 Peças (Blue Star) CORTADOR REGUA MINIATURA BLUE STAR Tamanho (Cm): 8,6 x 1,1 cm Tamanho médio de cada miniatura: 1,5 cm Profundidade cada miniatura: 0,50 cm Produto indicado para cortar biscuit, pasta americana, porcelana fria, argila, pasta de açúcar, massa de modelar e massa de EVA. Kit cortador produzido pela Blue Star Net que é uma indústria 100% nacional e a maior fabricante de ferramentas plásticas para artesanato e confeitaria do Brasil. Os produtos desenvolvidos pela Blue Star são confeccionados nos mais altos padrões de qualidade. O artesão que trabalha com modelagem de Biscuit e Confeitaria precisa de ferramentas que garantam um acabamento perfeito e profissional. Quando se trabalha com ferramentas corretas e profissionais o artesão produz em dobro e com qualidade. Cortadores para Confeitaria e Artesanato, temos diversos formatos e modelos. Produzida em material plástico resistente (PSC) (PSAI) poliestireno cristal e poliestireno alto impacto.', 21.2, 21.2, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/br-11134207-820li-mqx693n7ivpi07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F21598954339', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
