INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41260362663', 'Vitamina B12 Gotas Sabor Uva 20 ML Lauton Nutrition', 'Vitamina B12 em Gotas Metilcobalamina 9,94mcg 20ml A vitamina B12 contribui no desenvolvimento de células vermelhas, um processo importante para nosso organismo. Oferecemos a opção em gotas, proporcionando uma absorção mais rápida ao consumo. Utilizamos a fonte metilcobalamina, que tem uma melhor absorção, sendo a melhor opção a se adquirir. A vitamina B12 sublingual, em gotas, proporciona uma absorção mais rápida e é ideal para pessoas com dificuldade no consumo de comprimidos. Além disso, a vitamina B12 Lauton é livre de corantes, açúcar, glúten e qualquer crueldade animal.', 38.9, 38.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-mcm95nvld1rwdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965164614%2F41260362663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
