INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21976200645', 'Armário de Cozinha Completa 260cm Veneza Multimóveis V3708', 'O Armário de Cozinha Completa 260cm Veneza Multimóveis V3708 tem um excelente custo benefício e um amplo espaço interno. Produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. O balcão possui tampo removível (compatível com pia de 120 cm). Para deixar sua cozinha mais bonita e completa possui compartimento para utensílios mais altos e balcão para cooktop. Conteúdo da Embalagem: 1 (um) armário aéreo 120cm 1 (um) balcão com tampo 120cm 1 (um) balcão com tampo 70 cm 2 (dois) armários aéreos 70 cm Dimensões do produto montado: Altura: 203cm | Largura: 260cm | Profundidade: 32cm (aéreos) - 53cm (balcão com tampo) *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 1749.9, 1199.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qve9-li06oyt3puyo1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F21976200645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
