INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897971061', 'Grampeador Tapeceiro Manual com Kit 500 Grampos, Trena 2 Metros e Maleta SPARTA', 'Grampeador Tapeceiro Manual com Kit 500 Grampos, Trena 2 Metros e Maleta SPARTA Referência: 42003 A principal distincao deste jogo e que contem uma trena. Trabalhando com grampeador de tapeceiro muitas vezes ha necessidade de medicao, e este jogo universal permite armazenar todo necessario numa caixa. O jogo e embalado numa caixa de plastico com uma tampa transparente. O jogo contem grampeador de tapeceiro de metal, trena de medicao (2m) e 500 grampos de tipo 53. Ajuste de pressao suave. Grampeador e usado para trabalhos de estofamento de moveis, construcao de armarios e outro. com Trena 2M, 500 Grampos e Maleta. Sparta Ideal para trabalhos de tapeçaria onde é necessário armazenar materiais pequenos. Indicado para trabalhos de estofamento de móveis, construção de armários e outro. Informações: Grampos compatíveis tipo 53 de 6 a 14mm; Compacto e funcional corpo fabricado em aço; Punho: Emborrachado; Possui design ergonômico; Peso leve e de fácil operação; Maleta reforçada com display; Acompanha Trena 2m e 500 Grampos; Com Regulagem de Pressão. Itens inclusos: - 1 Grampeador tapeceiro - 1 Maleta reforçada - 1 Trena 2m - 500 Grampos * Imagens meramente ilustrativas.', 78.9, 78.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdx2-m1gz6dr0sncve8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F22897971061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
