INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398413484', 'Macaco Hidráulico Tipo Garrafa 12 Toneladas 2215 BREMEN', 'Macaco Hidráulico Tipo Garrafa 12 Toneladas 2215 BREMEN O Macaco Hidráulico Tipo Garrafa 12 Toneladas 2215 da marca Bremen é uma ferramenta robusta e eficiente, projetada para levantar cargas pesadas com segurança e precisão. Com capacidade de 12 toneladas, é ideal para uso em oficinas mecânicas, trabalhos de manutenção de veículos, e outras atividades que requerem elevação de grandes pesos. Este modelo possui um design compacto e resistente, facilitando o manuseio e o transporte. O corpo é construído em aço de alta qualidade, garantindo durabilidade e resistência à corrosão. A base larga proporciona maior estabilidade durante o uso, reduzindo o risco de acidentes. Além de ser feito em Aço, é indicado para elevação de cargas. Contém 1 pistão hidráulico e 1 fuso manual de ajuste. Possui 1 estágio. DADOS TÉCNICOS: Capacidade carga: 12t. Altura máximo: 345mm. Altura mínimo: 210mm. Curso do pistão: 135mm. Referência: 2215 Marca: Bremen Garantia: 3 Meses *Imagens meramente ilustrativas.', 242.92, 242.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Lift', 'https://cf.shopee.com.br/file/sg-11134201-7renr-m8ks1a07gj15ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F22398413484', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
