INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298420319', 'Jogo Brocas Bosch Para Madeira Com 7 Brocas', 'Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito. A Broca para Madeira Bosch de 3 Pontas executa perfurações precisas em madeiras macias e duras. Sua ponta centralizadora permite posicionamento exato para a perfuração e suas arestas de corte extremamente afiadas efetuam furos sem rasgos com alta precisão. O espiral duplo permite rápida saída de material evitando a obstrução do furo trazendo mais velocidade de perfuração. A broca possui encaixe cilíndrico e pode ser utilizada tanto para furos de passagem quanto de bolso. É indicada para perfurações em madeira, madeira dura, madeira maciça, madeira macia, placas de aglomerado de madeira, contraplacado e placas de madeira estratificadas, e utilização em Furadeiras, Parafusadeiras, Furadeiras de Coluna e Furadeiras de Bancada. - Medidas: 2, 3, 4, 5, 6, 8, 10mm - Quantidade: 7 Unidades Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito.', 149.9, 149.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8g7sy48wqup32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F350962329%2F22298420319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
