INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257918152', 'Sapato Mississipi de Salto Bloco Feminino J1472', 'Produto marca Mississipi. Eleve o seu visual com o Sapato Mississipi de Salto Bloco, a escolha perfeita para quem não abre mão do equilíbrio entre estilo e bem-estar. Com um design inspirado na tendência fisherman, este modelo apresenta tiras entrelaçadas que garantem um visual moderno e atemporal. Confeccionado em material sintético de alta qualidade e com acabamento monocromático, ele possui um salto bloco de 4,5 cm — a altura ideal para proporcionar estabilidade e conforto durante todo o dia, seja no trabalho ou em momentos de lazer. Este calçado é o aliado indispensável para uma rotina dinâmica. o fechamento em fivela no tornozelo oferece um ajuste seguro e personalizado, entregando a confiança que você precisa para caminhar com leveza. Graças à sua versatilidade, ele transita facilmente entre o casual e o elegante, permitindo combinações infinitas com vestidos, saias ou jeans. É o investimento inteligente para quem busca um sapato durável, leve, pesando apenas 0,757 kg e que traduz as principais tendências da moda atual com um toque de sofisticação prática. Sinta a liberdade de estar pronta para qualquer ocasião com um produto que une a qualidade reconhecida da Mississipi à necessidade de conforto do dia a dia. Não perca a oportunidade de renovar seu closet com uma peça que oferece máxima versatilidade e um design que valoriza sua personalidade. Garanta um visual impecável sem sacrificar o conforto dos seus pés e experimente a sensação de segurança a cada passo. Peso: 0,737 kg', 195.9, 169.9, NULL, 'Women Shoes > Flats > Ballet Flats', 'https://cf.shopee.com.br/file/sg-11134201-8260s-mmgh4bpacp3j21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F58257918152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194973164', 'Presunto Fatiado Seara', 'Presunto cozido fatiado Seara, feito com 100% de carne de pernil, ideal para lanches rápidos e práticos. Sem glúten e sem lactose, perfeito para diversas dietas e paladares. Experimente em sanduíches, saladas ou como acompanhamento em tábuas de frios. Mantenha refrigerado entre 0°C e 4°C para melhor conservação.', 12.79, 12.79, NULL, 'Food & Beverages > Bakery > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mqnelgeypvya20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554909%2F22194973164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
