INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22291636889', 'Máquina de Solda Inversora MIG Sem Gás 100A 110V FORTG', 'Loja do Mecânico - O que você precisa, nós temos! A máquina de solda com arco manual é uma das tecnologias mais tradicionais e eficientes em soldagem, sendo ideal para uso em ambientes industriais, oficinas, canteiros de obras e até mesmo em aplicações domésticas. Com excelente desempenho em diferentes tipos de aço e outros metais ferrosos, proporciona um acabamento de solda preciso e eficaz. Seu design leve, compacto e de fácil manuseio garante praticidade no transporte e na operação. Conta ainda com configurações ajustáveis conforme o diâmetro do eletrodo e a espessura da chapa a ser soldada, oferecendo maior versatilidade em seus projetos. Especificações Técnicas - Marca: FORTG - Tipo de Processo: MIG - Tensão: 127V - Frequência: 60Hz - Corrente de Entrada: 25A - Tensão em Vazio: 55V - Eficiência: 85% - Fator de Potência: 0,93 - Corrente de Solda (MIG): 40–100A - Ciclo de Trabalho: 100A @ 40%, 80A @ 100% - Classe de Isolação: IP21S - Classe de Proteção: F - Diâmetro do Arame: 0,8 mm a 1 mm - Dimensões (C x L x A): 350 x 250 x 260 mm - Peso: 5,6 kg -EAN: 7908591701128 Conteúdo da Embalagem - 01 Máquina de Solda - 01 Tocha Seca Embutida MIG - 01 Garra Negativa - 01 Escova de Aço Carbono - 01 Alça para Transporte Importante - Garantia de 06 meses; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 645.99, 645.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9t6ic7p7tq14b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fsh