INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393076773', 'Pano Reutilizável Scott Duramax Rolo Branco 174 Panos', 'Derrubou molho na pia ou espirrou na parede? Caiu gordura no fogão? Seu filho derramou um copo de suco na mesa ou no chão? O pano Scott Duramax Rolo resolve essas e outras emergências de maneira rápida, prática e higiênica! São mais absorventes e resistentes que papel toalha, podendo ser lavados e reutilizados ou simplesmente descartados, dependendo da sujeira • Use, lave e reuse. Seca rápido. • Não solta fiapos • Mais absorventes e resistentes que papel toalha • Prático e Higiênico: um pano limpo sempre à mão. Experimente a evolução da limpeza!', 49.29, 49.29, NULL, 'Home & Living > Home Care Supplies > Tissue & Paper Towels', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-lw7eeuppmbvfd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F22393076773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
