INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40425527832', 'Copo Tumbler Hanger 650ml Hello Kitty Zona Criativa - 10026586', 'Depois de um dia cheio de aventuras descobrindo novas brincadeiras, você precisa de uma mãozinha na hora de se hidratar? A gente te ajuda! Com 650ml de capacidade esse copo mata a sua sede! Não importa qual é a aventura, essa garrafa te acompanha em todos os lugares! O produto é importado, feito em aço inoxidável, possui detalhes incríveis que vão fazer você se apaixonar! Mesmo depois de um dia repleto de aventuras, combatendo o tédio, você não consegue combater a sede? Então esse copo é a companhia perfeita para os seus dias! Com 650 ml de capacidade, um canudo e parede dupla que te ajuda a manter a temperatura da sua bebida! Além de possuir uma alça para você carregar seu copo para onde você quiser! Não importa se você é uma gatinha ou não, esse copo te acompanha em todos as suas aventuras! Especificações: Altura: 19cm| Largura: 8,5cm| Comprimento: 8,5cm| Capacidade: 650ml| Material: Aço Inoxidável Cuidados e recomendações de uso: Não colocar o produto na geladeira ou congelador. Choques ou quedas podem danificar o produto. Lavar com água, esponja macia e sabão neutro. Não vai á lava-louças e nem ao micro-ondas. Não utilizar produtos químicos ou abrasivos. Características: - Marca:Zona Criativa - Modelo:10026586 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Copo Tumbler Hanger Hello Kitty', 153.88, 138.5, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-8257z-mg5bsbrija4r04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F40425527832', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
