INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23802004559', 'Shampoo Bio Extratus Neutro Proteinas Do Leite 500ml', 'O Shampoo Bio Extratus Neutro Proteínas Do Leite limpa e hidrata profundamente o cabelo secos deixando macios e com brilho. Sua formula Contém proteínas naturais para hidratar e realçar o brilho dos cabelos, sua formula é indicada para limpar delicadamente todos os tipos de cabelos, inclusive os cabelos tingidos. Sobre a Bio Extratus: Em 1997 a nossa produção já não era mais artesanal, éramos uma micro-empresa com uma marca cada vez mais forte e o nosso mercado ampliava. Foi neste período que a ousadia e visão de futuro dos proprietários superaram o medo das dificuldades e encorajaram a construção de uma nova fábrica, localizada no município de Alvinópolis a 170 Km da capital mineira. Em agosto de 1998 a Extratus Produtos Naturais passou a se chamar Bio Extratus Cosméticos Naturais. Como estratégia de crescimento, a marca prioriza a qualidade dos seus produtos e um relacionamento de valorização do público formador de opinião - os cabeleireiros. A Bio Extratus está presente em todo território nacional desde o início da década 90, com uma linha que cresce e se diversifica a cada ano, buscando realçar cada vez mais a beleza de seus cabelos.', 90.32, 90.32, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-82586-mqhx22dcq13fc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23802004559', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
