INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44559032332', 'Colar Gargantilha Feminino Vnox Com Contas Grossas De Resina Vintage – Design De Irregulares Em Ouro Banhado , Peça Curt', 'O Vnox da joia fala com joias Aço inoxidável de grau 316L (Seguro na pele e nas crianças, hipoalergênico e sem desbotamento) Tamanho: 43 + 8 cm ✈️Processamento e envio de processamento de envio✈️ Tempo de Chumbo: 1 A 3 Dias Envio de envio: cerca de 7 dias Perguntas frequentes 1) Desbota? (O banhado a ouro é difícil de desbotar. Manterá em boas condições dentro de 1-3 anos se você se importa com isso. Antes de enviarmos, cada um de nosso produto passa por testes QC. Se você tiver algum problema de qualidade após o recebimento do pacote, não hesite em contactar-nos a qualquer momento.) Ocasião de usar? Desgaste diário/festa/presente/engajamento/aniversário/casamento é adequado, deixe as joias VNox transmitirem seu amor)', 45.0, 22.5, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/sg-11134201-81zus-mn5kxt31isxw4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F239158067%2F44559032332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19533500846', 'Jogo De Soquetes Estriados com 22 Peças Encaixe 1/2" Vonder', 'Indicado para apertar e soltar porcas e parafusos sextavados, com o auxilio de acessórios manuais. Conhecido como jogo de pito/cachimbo. Produzido em aço cromo vanádio, proporcionando maior resistência e durabilidade. Conteúdo da Embalagem: 1 Jogo de soquetes, composto por 1 maleta plástica com 22 pecas, sendo: 18 soquetes estriados (8 mm, 9 mm, 10 mm, 11 mm, 12 mm, 13 mm, 14 mm, 15 mm, 16 mm, 17 mm, 18 mm, 19 mm, 21 mm, 22 mm, 24 mm, 27 mm, 30 mm e 32 mm), 1 catraca reversível, 1 cabo T, 1 extensão 5" e 1 extensão 10". Detalhes Técnicos: • Encaixe do soquete:1/2" • Tipo de soquete: Estriado • Material do jogo de soquete: Aço cromo vanádio • Torque máximo da catraca:512 N.m • Numero de pecas do jogo de soquete:22 pecas', 306.0, 269.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lk-mmqdrae74lc6ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F19533500846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694624365', 'Cropped Dois Lados Preto Poliamida Soft', 'Cropped Dois Lados Preto 2 EM 1 | Use de Duas Formas Estiloso e super versátil! O Cropped Dois Lados Preto 2 EM 1 da Donna Carioca apresenta um design inovador que pode ser usado de duas formas: com o decote em V mais profundo na frente para um visual ousado, ou nas costas para um toque de charme e sensualidade. Tecnologia Premium Excelência em Materiais: 90% Poliamida + 10% Elastano - Tecido macio para conforto o dia todo Proteção UV 50+ - Treino seguro ao ar livre Alta Elasticidade - Não esgarça durante o exercício Características de Design: Design Reversível 2 EM 1 - Use de duas formas diferentes Fita de Silicone Personalizada - Detalhe exclusivo no punho da manga Cós Anatômico - Ajuste perfeito que se mantém no lugar Bojo Removível - Conforto personalizável COMPRE AGORA - A mistura perfeita de praticidade e estilo!', 111.0, 111.0, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/sg-11134201-82595-mg80wmd6zuoca6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1576910750%2F23694624365', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098436805', 'Kit Máscara Tratamento OX Colágeno 300g Mais Óleo Capilar OX Nutritivo 3 Em 1 120ml', 'A Máscara de Tratamento OX Colágeno foi desenvolvida para recuperar cabelos porosos, secos e danificados. Sua fórmula com colágeno e aminoácidos de fontes naturais (soja, quinoa, trigo e arroz) repara a estrutura interna dos fios, promovendo hidratação profunda, brilho e maciez. Já o Óleo Capilar OX Nutritivo 3 em 1 (120ml) é ideal para revitalizar e nutrir cabelos ressecados e sem brilho. Com óleos essenciais de cálamo, mirra e oliva, atua como reparador de pontas, umectação noturna e booster de tratamento. Conta ainda com proteção térmica de até 230?°C e proteção UV, garantindo fios saudáveis e protegidos o dia todo. Modo de usar: Aplique a Máscara Ox nos cabelos úmidos, massageie e deixe agir por alguns minutos antes de enxaguar. Para intensificar o tratamento, misture 2 a 4 pumps do Óleo Nutritivo com a máscara, aplique nos cabelos e deixe agir por 5 minutos antes de enxaguar. Para reparar as pontas, aplique o Óleo Nutritivo nos cabelos úmidos ou secos, sem enxaguar Sobre a marca: OX Cosméticos é uma empresa brasileira do ramo de produtos cosméticos. Surgiu em 1995, como empresa, e ganhou notoriedade como fabricante de produtos oriundos de tutano de boi, desenvolvidos a partir de uma receita caseira da empresária Mariângela Bordon.', 75.57, 68.18, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-824go-mpdvds3cuadd31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22098436805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259691370', 'Budweiser Lata Sleek', 'A Budweiser é uma cerveja American Lager de sabor leve e aroma discreto, produzida com lascas de Beechwood, que conferem um sabor equilibrado. A mesma receita americana desde 1876. Harmoniza bem com hambúrguer clássico, presunto cozido e mix de castanhas.', 4.49, 4.49, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-8258j-mqnekmy2j4lpee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554990%2F58259691370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597475026', 'Radiador Suzuki Sx4 2.0 16v 2008 a 2013 Automático Sem Ar', 'Radiador Suzuki Sx4 2.0 16V 2008 a 2013 Da Marca Procooler Serve no meu Veiculo: Suzuki Sx4 2.0 16V 2008 a 2013 Especificações: - Tecnologia: Brasado - Combustível: Gasolina - Transmissão: Automático - Medidas: 375X718X16Mm - Indicado Para Veículos SEM Ar Condicionado Marca: Procooler Código do Fabricante: PC100122 Código da Montadora: - 1770080J10 EAN: 7899430205658 Peso: 4.4kg Medidas da Embalagem (a x l x p): 585x145x790mm Código de outras marcas (Referência cruzada): IR48808: IRB NT-4645.126: NOTUS 1770080J10: ORIGINAL OEM O PRODUTO O radiador é um trocador de calor que tem como função dissipar o calor que circula no sistema de arrefecimento para manter a temperatura de funcionamento do motor num patamar ideal na casa dos 90 graus celsius. SOBRE A MARCA A PROCOOLER é uma marca especializada no desenvolvimento de componentes para sistemas de arrefecimento e climatização automotiva das linhas leve, pesada, agrícola e de construção civil. A marca oferece ao mercado de peças de reposição, produtos de alta performance e durabilidade, aliadas a qualidade exigida pelas montadoras. IMPORTANTE: - Produto Novo - Imagens Ilustrativas - Garantia de 6 meses pelo Fabricante - Indicamos que a instalação seja realizada por um profissional habilitado, mantendo a garantida do produto. - Atenção: Em caso de vendas para Pessoa Jurídica poderá haver incidência de ST (substituição tributária) que será calculada e cobrada a parte do cliente após o fechamento da compra, para então liberar o despacho da mercadoria. PONTOS DE ATENÇÃO AO COMPRAR UM RADIADOR! Ao comprar um radiador é importante checar se o modelo da peça é adequado para o seu veículo. Evite imprevistos, confira com atenção as aplicações listadas na descrição deste anúncio e compare com as especificações do seu veículo, tais como: - Motorização - Ano de fabricação - Modelo - Câmbio manual ou automático - Com ou sem ar-condicionado - Tipo de combustível E aí? Ficou com dúvida? - Tente encontrar e nos passar o código de montadora do radiador instalado em seu veículo, este código é normalmente encontrado em uma etiqueta colada em uma das laterais da peça, mais especificamente na parte plástica. - Realize a comparação visual entre a peça anunciada e a peça instalada em seu veículo. - Verifique as saídas de água e suas posições e as compare com as saídas de água da peça instalada em seu veículo. - Compare as Dimensões da peça anunciada com as dimensões da peça instalada em seu veículo, lembrando que a altura do radiador é a medida entre as caixas laterais (partes plásticas onde normalmente são encontradas as saídas de água). - Fique atento ao tipo de câmbio do seu veículo, manual ou automático pois isso influencia na aplicação da peça. - Confirme se a peça anunciada é para veículos com ou sem ar-condicionado ou se possui aplicação para os dois casos. - Se ainda assim ficar com dúvidas, nos mande uma pergunta.', 630.99, 630.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/br-11134201-7r98o-mae8ice8cbrj64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548632689%2F22597475026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094083607', 'Manteiga Capilar Widi Care Juba Butter Oil Super Hidratante 300g', 'A Manteiga Capilar Widi Care Juba Butter Oil Super Hidratante foi desenvolvida para cuidar profundamente dos cabelos cacheados, crespos e ondulados, que precisam de hidratação intensa, nutrição e reposição de umidade. Com sua fórmula rica em óleos e manteigas vegetais, ela proporciona maciez, maleabilidade e muito brilho, além de combater o ressecamento dos fios. Sua textura cremosa e emoliente penetra na fibra capilar, devolvendo a umidade natural, selando as cutículas e garantindo cachos definidos, leves e saudáveis. Benefícios:• Reposição de umidade profunda• Hidratação intensa e duradoura• Ação condicionante com muito brilho e maciez• Melhora a maleabilidade dos fios• Ideal para cabelos ressecados, opacos e sem definição Modo de Uso: Após lavar os cabelos, aplique a Manteiga Juba Butter Oil mecha a mecha, no comprimento e pontas. Deixe agir de 5 a 10 minutos e enxágue bem. Use de 1 a 2 vezes por semana ou sempre que seus fios precisarem de um cuidado extra. Sobre a Widi Care: Com mais de 10 anos de atuação no mercado da beleza, a marca iniciou sua trajetória atendendo os principais salões do Rio de Janeiro e, posteriormente, expandiu sua presença por todo o Brasil com linhas profissionais. Em 2016, passou a fazer parte da rotina das consumidoras com o lançamento da linha home care, desenvolvida para todos os tipos de fios -cacheados, lisos, alisados ou coloridos. Tudo isso baseado em um princípio essencial: toda beleza importa. • Garanta cabelos extremamente hidratados, nutridos e cheios de vida com a Manteiga Juba Butter Oil Widi Care!', 62.09, 62.09, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261u-mm7jpiap6cxx21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22094083607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394684182', 'NIVEL DE ALUMINIO FERROVIARIO, REFORCADO, 2 BOLHAS + 1 ROTATIVA, 40POL., 1000MM, 1PC // MTX', 'O Nível de Alumínio Reforçado MTX Rail 340109, com um comprimento impressionante de 1000 mm, é uma ferramenta de precisão essencial para uma ampla gama de profissionais, incluindo construtores, acabadores, concretistas, entre outros. Este nível foi projetado para facilitar a verificação e o alinhamento de superfícies em relação aos planos horizontal e vertical, garantindo que todas as superfícies sejam mantidas perfeitamente planas e alinhadas, o que é crucial para a qualidade e a precisão dos projetos de construção e acabamento. Características e Benefícios: Versatilidade de Medição: Equipado com três bolhas, o Nível MTX Rail oferece a capacidade de verificar com precisão as superfícies em relação aos planos horizontal e vertical. A bolha giratória é um recurso particularmente valioso, pois permite o alinhamento de ângulos de 45 graus, tornando a ferramenta extremamente útil em uma variedade de aplicações e projetos que requerem medidas angulares específicas. Construção Robusta: A estrutura deste nível, feita de perfil de alumínio em forma de viga dupla, não apenas fornece uma resistência estrutural excepcional, mas também aumenta sua rigidez. Esta construção assegura que a ferramenta possa resistir ao desgaste do uso contínuo, mantendo sua forma e funcionalidade ao longo do tempo, mesmo em condições de trabalho exigentes. Principais Vantagens: Durabilidade e Resistência: A construção em perfil de alumínio em forma de viga dupla confere ao nível uma robustez inigualável, tornando-o resistente a impactos mecânicos e garantindo uma longa vida útil mesmo sob condições de trabalho intensivas. Adaptabilidade para Trabalhos Hidráulicos: A base em forma de V é uma característica inovadora que permite fixar o nível em tubos, oferecendo estabilidade e precisão adicionais em trabalhos hidráulicos. Este recurso é especialmente útil para profissionais que frequentemente enfrentam o desafio de trabalhar com tubulações, proporcionando facilidade e eficiência. Precisão Aprimorada: A base fresada do nível minimiza a imprecisão das medições para 1 mm/m (0,057 graus), garantindo medições extremamente precisas. Esta alta precisão é fundamental para assegurar que os projetos sejam realizados com a máxima exatidão, atendendo às especificações técnicas e aos padrões de qualidade exigidos. Orientações para Uso Eficiente: Para medições precisas de desvio vertical de 90 graus, é crucial utilizar a bolha de nível na posição superior. A superfície de base, oposta à bolha em 180 graus, serve como a superfície de trabalho, fornecendo um ponto de referência confiável para medições precisas e confiáveis. O Nível de Alumínio Reforçado MTX Rail 340109 é mais do que uma ferramenta; é um investimento na qualidade e precisão dos seus projetos. Combinando funcionalidades avançadas, construção durável e precisão excepcional, este nível é indispensável para profissionais que exigem o melhor em suas construções e acabamentos, assegurando resultados consistentemente precisos e de alta qualidade.', 88.87, 88.87, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821en-mgxn134im0wdbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F22394684182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097931015', 'Kit 04 Calotas Polo Track Aro 15 para Roda de Ferro 2021 2022 2023 2024', 'O kit de 4 calotas do Polo Track de 2021 a 2024, aro 15, é uma solução ideal para quem deseja renovar a aparência do veículo com estilo e praticidade. Cada calota é projetada para proporcionar um visual moderno e dinâmico, ao mesmo tempo que oferece proteção e funcionalidade.Características Principais:Material: Fabricadas em plástico de alta resistência, as calotas garantem durabilidade e resistência a impactos, além de suportar variações climáticas, mantendo a estética intacta.Diâmetro: Com aro de 15 polegadas, o kit é perfeitamente compatível com os pneus do Polo Track, assegurando um encaixe ideal.Altura do Cubo: A altura do cubo é padrão, resultando em um visual mais próximo ao da roda. Essa característica não só melhora a estética, mas também contribui para a leveza do conjunto, favorecendo o desempenho do veículo.Design: O design arrojado das calotas combina acabamento detalhado, criando um visual esportivo e sofisticado. As aberturas são estrategicamente posicionadas para permitir a ventilação dos freios, ajudando na dissipação de calor.Instalação: O kit é fácil de instalar, permitindo que o usuário coloque as calotas rapidamente, sem necessidade de ferramentas especiais. O sistema de encaixe é seguro, garantindo que as calotas fiquem firmemente fixadas.Manutenção: As calotas são de fácil limpeza, podendo ser lavadas com água e sabão neutro. A superfície é projetada para resistir a riscos e manchas, assegurando que se mantenham com aparência nova por mais tempo.Benefícios:Estética: O kit de 4 calotas transforma a aparência do veículo, adicionando um toque esportivo e contemporâneo.Proteção: As calotas protegem as rodas de sujeira e pequenos impactos, prolongando a vida útil dos componentes.Desempenho: A leveza e o design aerodinâmico das calotas podem contribuir para uma leve melhora na eficiência de combustível.', 121.5, 121.5, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Wheel Cover', 'https://cf.shopee.com.br/file/sg-11134201-7rdvp-m18ub5rl0m0u70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322429563%2F22097931015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192861715', 'Shiftpower Faaftech FT-SP18+ - Chip Módulo de Potencia Tira Delay Lag Atraso Pedal Acelerador', 'Carroussel Auto apresenta: O Shiftpower Faaftech para eliminar o atraso do acelerador! # # # # # # # # Encontre abaixo o VEÍCULO + ANO MODELO para RECEBER o modelo CORRETO # # # # # # # # É só encaixar no pedal acelerador e escolher entre os 4 modos de aceleração, 2 de segurança e 1 de economia! E pelo aplicativo você personaliza todos os detalhes de cada modo! ______ #MODOS DE CONDUÇÃO# - DYNAMIC (botão verde)- Resposta suave. Ganho confortável de aceleração proporcionando maior prazer ao dirigir - SPORT (botão amarelo) - Resposta média-rápida. Para uso na cidade - SUPER SPORT (botão laranja) - Resposta rápida com tocada mais esportiva. Para uso em rodovias - RACE (botão vermelho) - Resposta extremamente agressiva. Para uso em track days e em rodovias para ultrapassagens rápidas e seguras - MANOBRISTA (botão azul) - Limita o pedal do acelerador em 30%, com ajuste entre 15 a 45% pelo app - BLOQUEIO (botão alternando entre azul e branco) - Anula a resposta total do acelerador, protegendo seu veículo contra furto ou roubo - ECO (botão alternando entre verde e branco) - Diminui a resposta de aceleração em até 20%, com ajuste entre 0 a 20% pelo app ______ #BOTÃO LUMINOSO# - Altera entre os modos - Instalação opcional se preferir controlar pelo app ______ #APLICATIVO BLUETOOTH# - Compatível com Android e iOS - Altera entre os modos - Personaliza os modos salvando na memória do módulo - Uso opcional se preferir controlar pelo botão ______ #CONTEÚDO DA EMBALAGEM# - 1 Módulo ShiftPower - 1 Botão seletor luminoso com fita autoadesiva - 1 Cabo de instalação com encaixes do veículo escolhido - 2 Abraçadeiras - Manual do usuário com certificado de garantia - 1 Adesivo exclusivo ShiftPower ______ #COMPATIBILIDADE# Audi Audi A1 2015 até 2019 Audi A3 2007 até 2024 Audi A4 2009 até 2015 Audi A5 2007 até 2016 Audi A6 2008 até 2018 Audi A7 2011 até 2018 Audi A8 2010 até 2019 Audi Q3 2009 até 2024 Audi Q5 2008 até 2017 Audi R8 2006 até 2023 Audi RS 3 2011 até 2023 Audi RS 4 2008 até 2016 Audi RS 5 2007 até 2016 Audi RS 6 2008 até 2018 Audi RS 7 2011 até 2020 Audi RS Q3 2012 até 2023 Audi S3 2004 até 2022 Audi S4 2008 até 2016 Audi S5 2007 até 2016 Audi S7 2011 até 2017 Audi S8 2011 até 2018 Audi SQ5 2008 até 2017 Audi TT 2006 até 2019 Audi TTRS 2010 até 2019 Porsche Porsche 718 2017 até 2023 Porsche 911 2005 até 2021 Porsche Boxster 2005 até 2023 Porsche Cayman 2006 até 2022 Porsche Macan 2014 até 2023 Porsche Panamera 2009 até 2022 Volkswagen Volkswagen Arteon 2018 até 2023 Volkswagen Atlas 2018 até 2024 Volkswagen Beetle 2011 até 2019 Volkswagen CC 2012 até 2015 Volkswagen EOS 2007 até 2016 Volkswagen Fusca 2012 até 2016 Volkswagen Golf 2014 até 2020 Volkswagen Jetta 2005 até 2024 Volkswagen Nivus 2021 até 2025 Volkswagen Passat 2005 até 2021 Volkswagen Polo 2018 até 2025 Volkswagen Rabbit 2006 até 2009 Volkswagen T-Cross 2019 até 2025 Volkswagen Taos 2022 até 2024 Volkswagen Tiguan 2007 até 2024 Volkswagen Up 2011 até 2021 Volkswagen Virtus 2018 até 2025 ______ #OBSERVAÇÕES# - Garantia de fábrica: 3 anos contra defeitos na fabricação - NÃO acompanha aparelho celular, imagem meramente ilustrativa - NÃO acompanha chaveiro, imagem meramente decorativa', 776.67, 699.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5oowwve7j2o3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1183527021%2F23192861715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9970336252', 'Livro Literatura infantil A lagarta comilona', 'A lagarta quer muito voar. Mas tudo o que ela faz é comer e mastigar as folhas de um arbusto de amora. Até que a borboleta chega com um sorriso misterioso, pois sabe de algo que a lagarta não sabe! Qual será o segredo?_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2013_x000D_ Autor: Sheridan Cain_x000D_ Ilustrador: Jack Tickle_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 26.50 x A 23.00 x E 0.30_x000D_ ISBN: 9788538045533_x000D_ Coleção: Histórias emocionantes_x000D_ Linha Editorial: Ciranda na Escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Transformação, Surpresa, Natureza, Ciências Naturais, Pluralidade Cultural, Meio ambiente_x000D_ BISAC: Literatura Infantil / Natureza & Mundo Natural_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 39.9, 27.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdy8-m0yl79taqfwf5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9970336252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42364171363', 'Livro Sonoro Aventura Pirata', 'Explore os sons no caminho a uma caça ao tesouro divertida e conheça uma ilha perdida neste colorido livro sonoro!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Ilustrador: Louise Anglicas_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 23.00 x A 26.00 x E 1.50_x000D_ ISBN: 9786526120255_x000D_ Coleção: Aventuras com 10 sons / Carry-along noisy adventure_x000D_ Linha Editorial: Ciranda Cultural - Coedição_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Aventura, Sons, Pirata, História, Diversão_x000D_ BISAC: Literatura Infantil / Literatura Infantil / Ação e Aventura / Piratas_x000D_ Linha de Produto: Sonoro_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Laminação fosca_x000D_ Material: Cartonado', 99.9, 99.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-mdneqmy3pxgke0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42364171363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22434417609', 'Caneta esferográfica Cristal 1.0mm Vermelha caixa com 50 unidades Bic', 'Produto certificado no âmbito brasileiro de qualidade, conforme Portaria Inmetro Nº 333/2012: Segurança, Compulsório, Registro 000911/2015, OCP0040, INMETRO Caneta esferográfica clássica e favorita em milhares de lares, escritórios e escolas no mundo. Possui corpo hexagonal que assegura o conforto na escrita e transparente para visualização da tinta. Tinta de alta qualidade, que seca rapidamente evitando borrões na escrita. Maior Durabilidade: Escreve até 2 Km. Escrita macia. Fabricada com a quantidade certa de matéria-prima para uso prolongado e seguro. Não contém PVC. Possui tampa da mesma cor da tinta e também é ventilada em conformidade com padrão ISO. Na ponta conta com uma esfera de Tungstênio, perfeita e muito resistente, quase mais duras que o diamante. 100% das esferográficas são feitas por um processo altamente controlado. Desde seus início em 1950, a Companhia vem aperfeiçoando as máquinas e os processos de fabricação necessários para produzir canetas de alta qualidade e produzidas em massa. Detalhes: - Corpo transparente; - Corpo hexagonal não rola na mesa. - A cor da tampa indica a cor da tinta. - Tampa ventilada. - Ponta média de cobre de 1.0 mm com esfera de tungstênio.', 65.52, 52.42, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-81zur-mmj1lr5ahp8k04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616550287%2F22434417609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
