INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692041304', 'Terminal Bateria Automotiva C/ Isolador Conexões Elétricas', 'Terminal de Bateria Automotiva com Isolador é um modelo universal para conexões elétricas em veículos e equipamentes. APLICAÇÃO: - Universal (carros, camionetes, motos, barcos, máquina e e ESPECIFICAÇÕES TÉCNICAS: - Fabricante DNI Material: Metal Terminal de bateria automotiva com Isolador; Aplicação: Veículos da linha leve e pesada, barcos, motos, máquinas e equipamentos diversos; Para cabos de 10,00mm² a 25,00mm² Dimensões aproximadas: 3,3 x 6,3 x 2,2cm Modelo: DNI 7573 CONTÉM: - 1 Kit de terminais Dica: Utilize cabos de bateria extra produzidos com cobre eletrolítico de têmpera mole, recozidos e recobertos com composto de PVC de alta qualidade, para o máximo rendimento de sua instalação. IMPORTANTE: A Loja do Som e Acessórios recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 30.9, 30.9, NULL, 'Mobile & Gadgets > Accessories > Powerbanks & Batteries', 'https://cf.shopee.com.br/file/sg-11134201-7qve8-lk836ljwi4iz3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F22692041304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393232110', 'Kit com 3 Scotchgard 3M Protetor de Tecidos Repelente a Agua SPRAY 353ML', 'ScotchGard Protetor de Tecidos Spray 3M Detalhes do produto: O Scotchgard 3M Spray Impermeabilizante Protetor de Tecidos 3M é um protetor de fácil aplicação que envolve cada fibra do tecido, protegendo-a sem alterar a sua aparência e a sua maciez. Scotchgard 3M já é sinônimo de proteção no segmento de imóveis. Fácil de aplicar, o Scotchgard 3M protege artigos como móveis, roupas, bancos de automóveis, acolchoados, telas de tecidos, toalhas de mesa, barracas, bolsas, tênis de tecido, guarda-chuvas, gravatas, etc. Inofensivo para a camada de ozônio. Caracteristicas: Sua função é proteger, evitando desbotamento, desgaste, evitando parcialmente manchas no tecido, etc. Fazendo assim, com que o tecido fique com aspecto de novo por muito mais tempo. Lógico, que irá repelir água também mas não é 100% e é muito difícil um produto no mercado repelir 100% de água. Use agora mesmo Scotchgard 3M nos bancos do seu veículo e no estofado da sua casa para impermeabilizar tecidos. Após ver o resultado da impermeabilização do Scotchgard 3M, se arrependerá por não ter conhecido antes esse maravilho produto que é o Scotchgard 3M. Scotchgard 3M é uma tecnologia desenvolvida pela 3M. Impermeabilizante tecido.Scotchgard 3M vinha com 378ml mas agora vem com 353ml, redução de 6,6% no volume. Esta redução foi feita em 2012.Em 2003, o protetor Scotchgard 3M, mais uma grande inovação da 3M, completou 50 anos. E, depois de meio século de vida, o repelente a líquidos causadores de manchas, desenvolvido para proteger produtos têxteis - carpetes, móveis, toalhas de mesa e até mesmo roupas - e deixá-los com boa aparência por mais tempo, já virou sinônimo de categoria. OBS: Não utilize o produto em tapetes, carpetes, couro, suede e camurça!!! Conteúdo: 353ml Composição: Destilados de petróleo leves hidrotratados; Gases liquefeitos de petróleo; Mistura de silicone; Resina; Reticulante. (Pode haver alterção do fabricante sem aviso prévio). Rendimento: O conteudo de uma lata protege 1 sofá de tamanho médio, 2 cadeiras ou 5 jaquetas. A cobertura varia de acordo com tamanho, tipo de tecido e quantidade aplicada.', 299.7, 299.7, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7rdyd-lz0k8fl6kugc22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F22393232110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399857961', 'PAR DE LÂMPADA PY21W LED PHILIPS ULTINON PRO 3100 ÂMBAR 12V 1 POLO LUZ SETA RÉ FREIO INDICADORES', 'PAR DE LÂMPADA LED PHILIPS ULTINON PRO 3100 PY21W ÂMBAR 12V SKU: 11496AU31B2 DEIXE SEU AUTOMÓVEL AINDA MAIS MODERNO COM AS LUZES INDICADORES LED [~PY21W] PHILIPS ULTINON PRO3100 ÂMBARES. SINALIZE COM SEGURANÇA E ELEGÂNCIA COM UMA LUZ ÂMBAR BRILHANTE E INTENSA!! ESPECIFICAÇÕES TÉCNICAS: * APLICAÇÃO: INDICADORES DE DIREÇÃO DIANTEIROS E TRASEIROS * BASE: BAU15S * DESIGNAÇÃO: LED-AMBER [~PY21W] * HOMOLOGAÇÃO ECE: NÃO * LINHA: ULTINON PRO3100 * TECNOLOGIA: LED * TIPO: LED-AMBER [~PY21W] * VIDA ÚLTIL: 3.000 HORAS * LÚMENS: 140 * TEMPERATURA DE COR: ÂMBAR * POTÊNCIA: 2,15W * VOLTAGEM: 12 V', 158.44, 158.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg6wuyqpux3825', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432660571%2F18399857961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
