INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206606819', 'Bioderma Sensibio DS+ - Creme Hidratante Facial 40ml', 'Gel-creme antidescamaçãopara peles sensíveis, com tendência à vermelhidão com descamação e oleosas. Bioderma Sensibio DS+ acalma a irritação e promove sensação de alívio instantâneo, além de combater o aspecto descascado. O Gel Creme Bioderma Sensibio DS+ hidrata profundamente e ajuda a brecar a proliferação dos agentes irritantes que agravam a condição das peles com tendência a reações como vermelhidão e descamação. Sua inovadora textura gel creme, combinada à exclusiva tecnologia Quick Break e a um poderoso mix de ativos emolientes, permite que a água presente na fórmula penetre de maneira rápida e eficiente, oferecendo conforto imediato. Fórmula não-comedogênica, livre de perfumes e ideal para peles oleosas ou com dermatite seborreica. Hipoalergênica, sem corantes, parabenos e fragrância. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 143.9, 143.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-8260r-mlmi6l28p5hh3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58206606819', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253177558', 'Cetaphil - Loção Hidratante 473ml', '﻿Loção hidratante corporal e facial, para peles sensíveis, equilibradas e secas.Cetaphil Loção Hidratantehidrata instantaneamente com ação profunda e prolongada. A Loção Hidratante Cetaphil apresenta uma textura leve e pode ser utilizada tanto no rosto e quanto no corpo. Sua fórmula é enriquecida com Niacinamida, Pantenol e Glicerina, que ajuda a fortalecer a barreira cutânea em 24 horas. Entre as principais características, temos: • Estimulação de 15 ceramidas que a pele necessita. • Fortalecimento da barreira cutânea em 24 horas. • Pele mais macia já na primeira aplicação(94%).* • Rápida absorção graças à textura leve de fácil penetração. • Hidratação 360º com ingredientes emolientes, oclusivos e umectantes. * Estudo realizado com 36 participantes durante 28 dias de aplicação. **Nova embalagem. Você poderá receber o produto com a embalagem antiga enquanto durarem os estoques. Como usar: Aplicar após o banho e repetir a aplicação sempre que necessário. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 89.9, 89.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-8260v-mjfj8lzuitja0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253177558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
