INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48803145930', 'Papel Chumbo 8x7,8cm Bombom Trufa 300 Unidades Rose Gold', 'O Papel Chumbo Rose Gold é produzido em alumínio especial para bombons, oferecendo proteção, brilho e acabamento profissional para suas criações na confeitaria. Com tamanho ideal para envolver bombons, trufas, mini tabletes e outras peças delicadas, ele garante ótima maleabilidade, permitindo moldar e ajustar ao formato do doce sem rasgar. Além de valorizar a aparência final com seu brilho característico, o papel chumbo também auxilia na conservação, protegendo contra umidade, odores externos e variações de temperatura. Prático, resistente e indispensável para quem busca apresentação impecável, ele é a escolha certa para embalar doces com elegância, segurança e durabilidade. Quantidade: 300 unidades.', 35.24, 24.67, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mia6ee9wf3lt99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F48803145930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
