INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493106964', 'Crimes ilustrados - Record', 'Você é capaz de desvendar um assassinato apenas analisando a cena do crime? Neste livro interativo que reúne os jogos populares de Modesto García nas redes sociais e ilustrado por Javi de Castro, desperte o detetive que há em você seguindo as pistas para solucionar o crime. Transforme-se em um verdadeiro detetive de homicídios e comece a reunir as evidências porque aqui, para desvendar o crime, você precisará de todas as suas habilidades de observação e dedução. Por que há uma garrafa quebrada no chão? A quem pertencem estas pegadas? O que a vítima queria dizer com a última mensagem que deixou? Vá juntando aos poucos as peças do quebra-cabeças para descobrir o que aconteceu e quem é o verdadeiro culpado.Crimes ilustrados vai te prender com sua inovação, criatividade e originalidade. Com doze casos aguardando solução, o leitor precisa estar com suas habilidades investigativas afiadas para desvendar o mistério.São suicídios suspeitos, assassinatos sangrentos, disputas familiares por heranças multimilionárias, crimes passionais, identidades ocultas, segredos mortais...Você aceita o desafio?', 69.9, 69.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd5g-lwszio4jokd059', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23493106964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
