INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23391340145', 'Escova Tubular 1/2 Esmeril Chicote Aço Carbono Vonder 6325012000', 'Olá, Bem vindo a Distribuidora Brester. Trabalhamos com uma grande variedade de ferramentas elétricas e manuais, descartáveis, eletroeletrônicos, artigos para casa, artigos de petshop e outros. Aqui você encontrará Produtos Originais, Nota Fiscal, Pronta Entrega e Envio Imediato! * Características do produto * Escova Tubular 1/2" Esmeril Chicote Aço Carbono Vonder A Escova Tubular 1/2" da marca Vonder é a ferramenta ideal para a limpeza interna de tubulações e esmeril de chicote. Ela possui maior poder de remoção do que outras escovas, sendo mais eficaz e ágil. Seu design ergonômico permite trabalhos precisos e seguros. A Escova Tubular 1/2" da marca Vonder é fabricada com matérias-primas de alta qualidade, proporcionando maior resistência e durabilidade, permitindo que seja utilizada por mais tempo. Além disso, ela conta com um cabo de fácil manuseio, que proporciona maior segurança e conforto durante o uso. É a escova ideal para a limpeza interna de tubulações e esmeril de chicote. A Escova Tubular 1/2" da marca Vonder é ideal para profissionais que buscam um produto de qualidade para seus trabalhos. Aproveite e compre agora! Características Técnicas: > Material/acabamento das cerdas da escova: Aço carbono/polido; > Diâmetro: 12,70 mm; > Comprimento da área com cerdas (mm): 100 mm; > Comprimento total da escova (mm): 150 mm; > Rosca: 1/2" - 13 fios - UNC; > Massa aproximada (peso): 0,037 kg; - Marca: Vonder - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica. - Produto novo, com garantia de fábrica. - Produto a pronta entrega. - Envio em até 24hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester Máquinas.', 17.0, 15.26, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvcr-lhdh5n5u7dh3ea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F23391340145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293156142', 'Julieta de bicicleta - Cortez', 'Julieta é uma menina habituada a fazer tudo do seu jeito, ela nunca se engana e não admite mudanças. Até que... Um texto alegre, reflexivo e de ilustrações ricas em detalhes e coloridas, aborda assuntos importantes na fase de crescimento entre filhos e pais extremamente cuidadosos que, como forma de proteção, desestimulam as crianças e os jovens a encontrarem seu próprio caminho.', 58.82, 58.82, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-lxt39c0uqwa1ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22293156142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
