INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48309714881', 'Boneco Funko Pop! Star Wars Mandalorian e Grogu - Grogu', 'Traga toda a fofura e magia da galáxia muito, muito distante para sua coleção com o Boneco Funko Pop! Grogu. Inspirado no filme Mandalorian e Grogu, este colecionável em vinil com aproximadamente 9 centímetros captura o icônico personagem em detalhes encantadores, perfeito para fãs de todas as idades. Ideal para decorar prateleiras, mesas ou complementar sua coleção POP! Star Wars, o Funko Pop! Grogu combina charme, autenticidade e toda a personalidade que conquistou o coração dos fãs, tornando-se um item indispensável para colecionadores e amantes do universo Star Wars.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-820mt-mnn3fxamxmv536', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F48309714881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997982524', 'Boneco Funko Pop! Rides Deluxe Lotus - Ayrton Senna', 'Celebre o legado de Ayrton Senna com o Boneco Funko Pop! Rides Deluxe Ayrton Senna na Lotus Amarela! Essa peça exclusiva homenageia o icônico piloto brasileiro em seu emblemático carro de Fórmula 1 Lotus, trazendo detalhes que remetem ao auge de sua carreira. Ideal para fãs de automobilismo e colecionadores, o boneco de vinil é perfeito para compor uma coleção repleta de adrenalina e história do esporte. A figura de vinil tem aproximadamente 10 centímetros de altura. Adicione essa homenagem ao lendário Ayrton Senna à sua coleção e mantenha viva a memória de um dos maiores nomes da Fórmula 1!', 577.99, 577.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rfgo-m3w0bzc8wsq06f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F21997982524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
