INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097994205', 'Lixadeira Roto-Orbital 5'' Lrv 355 220V Vonder', 'Lixadeira roto-orbital 5", LRV 355, 220 V~, VONDER Possui formato ergonômico e controle de rotação, proporcionando maior comodidade e controle nos trabalhos. Utiliza discos de lixa com sistema fixa fácil (com pluma), que confere maior praticidade no momento da troca. Indicada para lixamento e acabamento em superfícies de madeiras e derivados. Especificações: Modelo: LRV 355 Potência: 350 W Capacidade da lixadeira (disco): 5" - 125 mm Tipo de velocidade: Variável - 6 velocidades Rotação em vazio da lixadeira (rpm): 8.000/min - 13.800/min Oscilação da lixadeira (opm): 8.000/min - 14.000/min Coletor de pó: Possui Tensão (V): 220 V~ Frequência (Hz): 50 Hz / 60 Hz Incerteza da aceleração transmitida nas mãos - braços do operador - k: 1,5 m/s² Aceleração transmitida nas mãos - braços do operador - ah: 4,67 m/s² Segue norma: IEC 62841-1 e IEC 62841-1-2-4 Massa aproximada (peso) (kg): 1,7 kg Conteúdo da Embalagem: 1 Lixadeira roto orbital. Acompanha: 1 coletor de pó, 1 adaptador para aspirador de pó, 2 lixas G80, 2 lixas G120 e 2 lixas G150.', 506.72, 361.74, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3azi51uovdn88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23097994205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
