INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098189769', 'Sandália Vizzano Salto Bloco Baixo Casual Feminina - Caramelo', 'Pra quem não abre mão de uma sandália elegante e versátil, te apresento a sandália da Vizzano, super comfy, moderna e mega estilosa. Confeccionada em material sintético de alta qualidade, possui ajuste por fivela no fechamento do calcanhar deixando o visual a super charmoso e confortável. Sua palmilha é super macia e garante muito conforto aos pés. Seu salto bloco baixo tem altura aproximadamente de 4cm de altura e é do tipo grosso. Seu solado é antiderrapante que promovem muito mais segurança ao andar. Peça já a sua!', 129.9, 109.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-7rbku-m5n2vyv4ay0w8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F22098189769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48351332302', 'Chinelo Kenner Ibiza Tomates Feminino - Branco e Vermelho', 'A linha Ibiza Estampada uma experiência muito além do esperado através da sua dupla camada: Palmilha com densidade controlada que proporciona maior conforto + solado de borracha vulcanizada.Suas estampas exclusivas refletem a força e o poder feminino. Seus detalhes não deixam dúvidas que a Kenner Ibiza é #MAISQUECHINELO. Compre já!', 139.9, 129.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-821d0-mh0jx1c76i2y62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F48351332302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297693944', 'Viseira Pro Tork Capacete Stealth Injetada 2,0 Mm Viseira Fumê Versão 2 Em Policarbonato', 'A viseira Stealth apresenta alta definição optics, para assim eliminar qualquer distorção. Estabelece um novo padrão de durabilidade em uma viseira, protegendo os seus olhos. ATENÇÃO: O produto em questão é compatível com todos os modelos de Stealth versão 2. Para saber se será compatível com o modelo que você possui, identifique por gentileza qual imagens. Especificações: - Viseira fumê; - Modelo: Todos os modelos de Stealth (versão 2); - Fabricada em policarbonato; - Acessório de reposição de fácil instalação; - Espessura de 2,0mm; - Dupla curvatura; - Marca: Pro Tork. A viseira pode ser substituída facilmente, pois possui sistema de troca rápida, para facilitar o uso das viseiras recomendadas em situações diurnas (fumê) e noturnas (transparente). Como fazer a limpeza: - Indicamos utilizar um pano úmido com detergente neutro e passá-lo nas partes internas, depois deixar secar na sombra. Observação: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 84.11, 44.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/sg-11134201-7rdyc-lycbkxnwjsbs68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22297693944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17729521630', 'Carenagem Bros 125-150 Sub Tampa Lateral Anos 2003 À 2008', 'As Carenagens e Peças plásticas Pro Tork são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricado em ABS 100% virgem, as carenagens Pro Tork são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Cor: Preto; - Marca: Pro Tork; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Valor referente ao par; - Moto compatível: - Honda NXR 125 Bros 2003 a 2005; - Honda NXR 150 Bros 2003 a 2008. Aplicação: - Honda NXR 125 Bros 2003; - Honda NXR 125 Bros 2004; - Honda NXR 125 Bros 2005. - Honda NXR 150 Bros 2003; - Honda NXR 150 Bros 2004; - Honda NXR 150 Bros 2005; - Honda NXR 150 Bros 2006; - Honda NXR 150 Bros 2007; - Honda NXR 150 Bros 2008. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada. A Sportbay não se responsabiliza pela má instalação do produto. Sportbay - Seu Esporte, Nossa Paixão.', 84.11, 39.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/2451169b40bfcf06a51f2e9c6c1db446', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F17729521630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203585099', 'Controle Fita Led Smart Musica RGB via Aplicativo Tuya', 'Controle Smart para Fita LED RGB Wi-Fi com App Tuya – Com ou Sem Música Transforme qualquer fita LED comum em iluminação inteligente de verdade. Controle cores, efeitos, brilho e automações direto pelo celular. Quer espetáculo? O modelo com música sincroniza a luz com o som. Quer simples e funcional? Tem versão sem música também. Modelos Disponíveis ✔ Modelo 1 – Controle RGB com Música ✔ Modelo 2 – Controle RGB sem Música (Escolha a variação correta no anúncio) Principais Funcionalidades 📱 Controle via aplicativo Tuya Smart / Smart Life 🎨 Milhões de cores RGB e efeitos dinâmicos 🔊 Modo Música (modelo 1): luzes sincronizam com o som ambiente ⏱️ Timer e agendamentos automáticos 🌐 Conexão Wi-Fi 2.4GHz 🎙️ Compatível com Alexa e Google Assistente 🎚️ Ajuste de brilho, velocidade e cenas Compatibilidade Fitas LED RGB 12V ou 24V (verifique sua fita) Uso interno Ideal para: quartos, salas, painéis, TVs, setups gamer e decoração Especificações Técnicas Controle: via App Tuya Conectividade: Wi-Fi 2.4GHz Cores: RGB Tensão de trabalho: conforme a fita LED utilizada Instalação: simples e rápida (plug & play) Diferença entre os Modelos Modelo com Música: reage ao som ambiente 🎵 Modelo sem Música: controle total de cores e efeitos 🎨 Conteúdo da Embalagem 1 a 3x Controle Smart para Fita LED (modelo conforme escolhido) ⚠️ Atenção: Não acompanha fita LED Verifique se sua fita é RGB (não compatível com RGBW) Wi-Fi precisa ser 2.4GHz', 40.0, 19.0, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjo0ts9lxrsyf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F58203585099', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256995195', 'Caixa Box De Som Gabinete Profissional Multiuso 2x15 + Ti', 'Ideal para alto-falantes de 15", esta caixa oferece desempenho superior, excelente acabamento e durabilidade. Produzida em MDF de 15 mm, conta com pintura texturizada (PU) e tela com pintura eletrostática, garantindo resistência e um design profissional. ESPECIFICAÇÕES Furação do alto-falante: 15 polegadas = 35,5 cm (diâmetro) Furação da corneta: 21,5 cm x 8,5 cm DIMENSÕES Altura: 108 cm Largura frontal: 46 cm | Largura traseira: 30cm Profundidade: 39 cm Peso: 14 kg CARACTERÍSTICAS Acompanha 2 speakons Pés de borracha Alça para transporte Copinho na parte inferior para suporte de pedestal/tripé ESSA CAIXA É VAZIA. NÃO ACOMPANHA EQUIPAMENTOS. Fabricada pela Boombastic Áudio & Design, referência nacional em qualidade e inovação no segmento de áudio profissional.', 998.0, 998.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mlw18fumwbgl51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1598756230%2F58256995195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
