INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697025536', 'Válvula Ar Quente Gm Vectra 1996 a 2010 - 150760 - 087087', 'Válvula Ar Quente Gm Vectra 1996 a 2010 150760 087087 3 VIAS Funciona como um interruptor, que libera/bloqueia a entrada do líquido de arrefecimento do motor ao radiador na caixa de ventilação. Quando o botão do controle de temperatura estiver em Frio, a válvula de ar quente recebe alimentação elétrica para impedir que o líquido de arrefecimento entre na caixa de ventilação, mantendo frio o ar que circula. Na posição Quente, a válvula desliga e não recebe alimentação elétrica, permitindo a entrada do líquido de arrefecimento, aquecendo o ar da ventilação.', 46.45, 46.45, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Air Conditioning', 'https://cf.shopee.com.br/file/sg-11134201-7rbk4-lmqn4yiljv6x0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23697025536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593584698', 'Filtro Ar Peugeot 2008 2015 a 2024 - 1352994 - FAP4873', 'Filtro Ar Peugeot 2008 2015 a 2024 1352994 FAP4873 1.6 16V - (Allure / Griffe) - automático / mecânico Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 41.01, 41.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rfhf-m3mlse96x6w74c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22593584698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
