INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599380795', 'Penteadeira Camarim 90x41cm 6 Soquetes 3 Gavetas Branca', 'Penteadeira Camarim, perfeita para você organizar seus itens de maquiagem, perfumes, escovas e acessórios em um só lugar, estrutura resistente em MDP de 15mm, tampo suporta até 25 kg, pintura com acabamento em UV (Brilho). Possui 03 gavetas com amplo espaço interno e com corrediças metálicas que suporta até 3kg, puxadores embutidos, interruptor com tomada ideal para conectar seu secador de cabelo, conta com 06 soquetes acoplados na moldura do espelho para lâmpadas (lâmpadas não inclusas). Indicamos a compra da lâmpada de LED na temperatura quente (luz amarela) na intensidade de 4 Watts para melhor iluminação ao maquiar-se. Este móvel chegará em sua casa separado em 01 volume. Especificações: - Altura: 142,5 cm - Largura: 90 cm - Profundidade: 41,5 cm - Sistema de Montagem: Parafusos, minifix e cavilhas. - Recomendação de Limpeza: Limpar com pano seco para retirar o pó. Não aplicar produtos abrasivos. - Não Acompanha Lâmpadas. - Produtos de Enfeite Não Estão Inclusos.', 1143.87, 759.9, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdw9-m05e6jm5mldm17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F21599380795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
