INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197368769', 'Pomada Para Prevenção De Assaduras Babymed Azul 45g - Kit 3 Unidades', 'DESCRIÇÃO DO PRODUTO Babymed pomada é ideal para proteger a pele do bebê contra assaduras. Indicada para prevenir assaduras, formando uma camada protetora na pele do bebê que a mantém longe do cocô e do xixi. Deixa a pele do bebê sempre hidratada e bem nutrida, pois possui em sua formulação as vitaminas A e E. Fácil de usar, espalhar, limpar e remover. Pomada dermatológica de uso tópico, externo e pediátrico. MODO DE USAR Limpe cuidadosamente a pele do bebê e aplique a pomada sobre a área a proteger, massageando suavemente. Utilize a cada troca de fraldas. CONTRAINDICAÇÕES Em casos de hipersensibilidade (alergia) aos componentes da fórmula. PRECAUÇÕES Se observar alguma reação desfavorável suspenda o uso e procure um médico. Não aplicar sobre a pele irritada ou ferida. Conservar em local fresco, seco e protegido da luz. Mantenha o produto fora do alcance de crianças.', 29.29, 25.9, NULL, 'Mom & Baby > Baby Healthcare > Baby Skincare', 'https://cf.shopee.com.br/file/sg-11134201-7r9as-llco6695bjp1d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F18197368769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
