INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47203247482', 'Lenços de Limpeza Facial NIVEA Ação Hidratante 3 em 1 25un', 'O que é? NIVEA Lenços de Limpeza Ação Hidratante 3 em 1 são lenços de limpeza suaves e eficazes, ideais para remover maquiagem, inclusive máscara à prova d’água. Além de limpar profundamente, eles proporcionam uma sensação de pele hidratada. Para que serve? Os lenços removem até a maquiagem mais resistente e máscaras à prova d''água, deixando a pele limpa e hidratada. Enriquecidos com óleo de amêndoas que limpa suavemente o seu rosto, enquanto o Complexo Suave com Pró-Vitamina B5 e Hidramina protege a pele contra o ressecamento. Benefícios e diferenciais: - Remove maquiagem e máscara para cílios à prova d''água - Limpa a pele profundamente - Hidrata a pele - Dermatologicamente e oftalmologicamente testado - Remove os resíduos e impurezas da pele - Limpa a pele gentilmente* *Teste em uso durante 2 semanas.', 32.22, 32.22, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-81zw9-mid1jzicxqf6b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F47203247482', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
