INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257122598', 'Calça Infantil Menino Moletom Piquê Colorittá Marrom', 'Peça-chave no guarda-roupa infantil, a Calça Colorittá é perfeita para compor looks casuais com conforto e estilo. Feita em moletom piquê, ela possui elástico no cós com cordão decorativo e punho nas barras, proporcionando liberdade de movimentos. Além disso, os bolsos laterais trazem praticidade para o dia a dia e o detalhe de etiqueta garante um toque moderno à peça. Ideal para todos os momentos, invista nesse item essencial para dias cheios de atitude e conforto!Detalhes da peça: • Feita em moletom piquê • Elástico no cós • Possui bolsos • Detalhe em etiqueta • Ideal para todos os momentos', 99.9, 69.93, NULL, 'Baby & Kids Fashion > Boy Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-8257u-mr1tq3084nif24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58257122598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
