INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593806945', 'Kit Reparador de Pontas Amend Gold Black 30ml (3 unidades)', 'Reparador Amend Gold Black Nutritivo forma uma película protetora em volta dos fios que condiciona, doa brilho, maciez e repara as pontas duplas e ressecadas. Ação: Forma uma película protetora em volta dos fios que condiciona, doa brilho, maciez e repara as pontas duplas e ressecadas. Modo de uso: Aplique nos cabelos secos ou úmidos, 2 ou 3 gotas na palma da mão e espalhe do comprimento dos fios até as pontas. Pode ser utilizado para modelar os cachos, amassando os fios suavemente. Não necessita enxaguar.', 85.02, 85.02, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd5l-m6zlzbu1jbdgf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22593806945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
