INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797539100', 'Protetor de Colchão para Solteiro Impermeável Vida Pratika Branco', 'Usar um protetor para colchão faz com que a necessidade de higienizá-lo torne-se menos frequente, pois evita que a sujeira tenha contato direto com ele. O protetor de colchão Vida Pratika não pode faltar na sua casa! Ele é feito de polipropileno, impermeável e vai proteger seu colchão contra ácaros, sujeiras indesejadas e poeira, aumentando o tempo de uso do seu colchão. Dicas de Preservação Siga as instruções de lavagem e conservação dispostas na etiqueta ou embalagem do produto. Recomenda-se higienizar o protetor de colchão pelo menos uma vez por semana.', 29.99, 29.99, NULL, 'Pets > Litter & Toilet > Others', 'https://cf.shopee.com.br/file/sg-11134201-820nv-mo45ygxtfmdg26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F22797539100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
