INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492580091', 'Odeio te amar - Editora Arqueiro', 'Inclui as histórias Sob o mesmo teto, Presa com você e Abaixo de zero. E um capítulo extra! Nesta coleção de três histórias românticas, Ali Hazelwood faz o leitor suspirar e gargalhar, brindando-o ainda com um capítulo especial com o ponto de vista de Liam, Erik e Ian. Mara, Sadie e Hannah são três grandes amigas e cientistas tentando equilibrar razão e emoção. Embora seus campos de estudo as tenham levado para diferentes partes do mundo, todas elas concordam com uma verdade universal: Quando se trata de amor e ciência, os opostos se atraem e algumas misturas podem ser perigosas… Engenheira ambiental, Mara descobre que a casa que recebeu de herança é um presente de grego quando se vê obrigada a compartilhar o mesmo teto com o outro herdeiro – Liam, um detestável advogado de uma empresa petroleira que faz de tudo para atormentá-la. Sadie é uma engenheira civil que se interessa por Erik depois de um encontro inesperado, mas ele acaba traindo sua confiança e os dois se afastam. Um dia, eles ficam presos juntos em um elevador de Nova York, e a rivalidade e o amor vão alcançar um novo patamar. Hannah está trabalhando em uma remota estação de pesquisa do Ártico quando sofre um acidente. A engenheira aeroespacial da Nasa precisa ser resgatada antes que morra de frio... Só não esperava que a única pessoa disposta a realizar a perigosa missão seja Ian, o sujeito que tentou arruinar sua carreira.', 49.9, 49.9, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/sg-11134201-7rbll-ln5v01il5wdddf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22492580091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
