INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44900953245', 'Chinelo Kenner Rakka Mono Marsala - Masculino', 'Design industrial, performance elevada e conforto amplificado! Chinelo Kenner Rakka Mono Marsala - Masculino Parte superior do formulário Parte superior do formulárioFicha Técnica: Marca: Kenner Cor: Marsala Cabedal: Tecido sarjado com tecnologia Hydro-off que repele água Gênero: Masculino Palmilha: EVA extra macio na marsala Sola: Borracha vulcanizada com peça amplificadora de altura Entressola: Anatômica com estrutura de suporte Indicado: Uso urbano, diário e pós-treino Detalhes: Pin metálico em banho preto fosco, design robusto com visual moderno, Re.Amp - peça que amplifica a altura e o conforto e Hydro-off - resistência à água Experimente a fusão perfeita entre design arrojado e tecnologia com o Chinelo Kenner Rakka! Porque investir: O cabedal com tecnologia Hydro-off repele água e oferece resistência extra para o dia a dia. A entressola anatômica, junto com a peça Re.Amp, proporciona uma elevação de conforto e estabilidade como você nunca viu. Ideal para quem quer praticidade sem abrir mão do estilo, seja no uso urbano ou no pós-treino. Conteúdo da embalagem: 1 par de Chinelo Kenner Rakka Mono Marsala - MasculinoParte superior do formulário Parte superior do formulário Parte superior do formulário', 199.99, 199.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-821d7-mgqyjyyk3vux84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F44900953245', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56304165846', 'Chinelo Kenner NK6 Pro Preto e Vermelho - Masculino', 'O equilíbrio perfeito entre potência, estilo e conforto! Chinelo Kenner NK6 Pro Preto e Vermelho – Masculino Ficha Técnica: Marca: Kenner Linha: NK6 Pro Gênero: Masculino Cor: Preto e vermelho Indicação: Uso diário, praia e dia a dia Cabedal: Nova tira zigue-zague na cor vermelho Palmilha: EVA extramacia na cor preta Solado: Tratorado de borracha vulcanizada, antiderrapante na cor vermelho Bico: Arredondado amplo e confortável, não sendo pontudo ou estreito Tira frontal: Duas tirar largas no peito do pé Formato: Forma padrão Tecnologias: Solado anatômico com alta tração, estrutura durável e confortável (reduz atrito com a pele) Detalhes: Identificador bimetal K Se você busca um chinelo com visual imponente, conforto de alto nível e tecnologia aplicada, o Kenner NK6 Pro é a sua escolha definitiva. Com nova tira frontal zigue-zague que garante um encaixe firme e estiloso, ele entrega performance para o dia a dia com solado tratorado antiderrapante em vermelho vibrante Por que investir: O Kenner NK6 Pro foi projetado para quem vive com intensidade, precisa de estabilidade e exige design moderno. Seu acabamento com identificador bimetal, somado ao conforto do solado anatômico, faz dele uma peça premium com excelente custo-benefício Conteúdo da embalagem: 1 Chinelo Kenner NK6 Pro Preto e Vermelho – Masculino', 149.99, 137.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-823ow-moh4qjh9qcr04b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F56304165846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
