INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209720263', 'Deo Parfum Natura Homem Coragio 100ml', 'Uma fragrância que celebra a coragem e a autenticidade.É o arrepio na pele das notas metálicas de especiarias frias e o calor da madeira copaíba e do cumaru, ingredientes naturais da biodiversidade brasileira.• Fragrância que exala coragem e autenticidade• Perfumação intensa e duradoura • Ideal para ocasiões especiais. GOTA OLFATIVA: Concentração:deo parfumFamília olfativa:amadeiradoNotas de topo:bergamota, pimenta preta, maçã, grapefruit, canela, menta, noz moscada e pimenta rosa.Notas de corpo:lavandin , muguet, rosa, angélica e couro.Notas de fundo:cedro, cistus lábdano, cumaru, âmbar e copaíba.Cruelty freeVeganoOcasião:para sair, ocasiões especiaisSubfamília:ambarado Coragem e autenticidade Natura Homem Cor.agio reflete a essência do homem autêntico e corajoso, com uma fragrância que combina frescor e profundidade. Aroma amadeirado e fresco,uma fragrância que equilibra o frescor das notas cítricas com a profundidade das madeiras, ideal para homens que valorizam a autenticidade e a coragem. COMO USAR:: Para uma melhor perfumação, aplique a fragrância em áreas de maior temperatura corporal, como punhos, pescoço, atrás das orelhas e dobras internas dos cotovelos.', 329.9, 329.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-820md-mnkhz4yhx1q8e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58209720263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
