INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209453130', 'Álcool Zumbi Tradicional', 'O Álcool Zumbi 46° INPM é ideal para a limpeza geral da casa, removendo sujeiras difíceis com praticidade e eficiência. Modo de uso: Aplique o produto sobre a superfície a ser limpa e espalhe com um pano. Para limpeza, utilize 100ml do produto para cada 1l de água. Produto não recomendado para superfícies sensíveis ao álcool.', 13.49, 13.49, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258l-mqnem2vnml8u2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209453130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209455841', 'Queijo Mussarela Président', 'O Queijo Mussarela Fatiado Président tem sabor suave, textura macia e fatias sempre soltinhas, perfeito para o preparo de misto quente, lasanhas e diversas outras receitas! Além disso, a embalagem pode ser armazenada fechada na geladeira por até 60 dias, e após aberta, pode ser mantida na mesma embalagem, proporcionando mais praticidade e sabor para o seu dia a dia. *Não contém glúten.', 13.49, 13.49, NULL, 'Food & Beverages > Dairy & Eggs > Cheese & Cheese Powder', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mqneli8a5yj22c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209455841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259450245', 'Cappuccino em Pó Clássico Gourmet Santa Mônica', 'Desfrute de um cappuccino cremoso e saboroso com o Cappuccino em Pó Clássico Gourmet Santa Mônica. Uma bebida perfeita para aquecer seus dias, seja no café da manhã ou no lanche da tarde. Feito com ingredientes de alta qualidade, como leite em pó integral, café solúvel e cacau em pó, o cappuccino Santa Mônica oferece um sabor clássico e irresistível. *Modo de preparo: Aqueça 100ml de leite. Em uma xícara, adicione 25g do cappuccino Santa Monica e acrescente parte do leite. Mexa bem até dissolver e coloque o restante do leite quente.', 30.99, 30.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-82584-mqnem19filfn57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259450245', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261400160', 'Cartucho de Tinta HP 668 Preto - 7FP37VL', 'Se você busca qualidade de impressão confiável, economia no dia a dia e total compatibilidade com sua impressora, o Cartucho de Tinta HP 668 Preto é a escolha ideal. Desenvolvido pela própria HP, este cartucho garante desempenho consistente desde a primeira até a última página, entregando textos nítidos, pretos intensos e acabamento profissional em todos os seus documentos. Sua instalação é simples e rápida, permitindo que você volte a imprimir em poucos minutos, sem necessidade de configurações complexas. Além disso, o sistema inteligente da HP possibilita o monitoramento do nível de tinta, evitando surpresas e interrupções inesperadas durante tarefas importantes. Outro diferencial está na qualidade da tinta. Com secagem rápida e formulação otimizada, o cartucho evita borrões e manchas, garantindo documentos mais limpos e profissionais. Especificações Técnicas Cartuchos e cabeçotes de impressão Rendimento 160 Rendimento por página (preto e branco) ~160 páginas Subgrupo Standard Capacity Cartridges Cor do cartucho Black Tecnologia Ink Volume do cartucho de impressão 3 ml Cor (es) dos suprimentos de impressão Preto Tipo de fornecimento Cartridges Nomes de produtos Subgrupo de produto Cartuchos de tinta de capacidade padrão Geográfico País de origem Cingapura Especificações da impressora Tecnologia de impressão HP Thermal Inkjet', 110.9, 110.9, NULL, 'Computers & Accessories > Printers & Scanners > Inks & Toners', 'https://cf.shopee.com.br/file/br-11134207-820lq-mophwr1bt69v0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1668186272%2F58261400160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20439104589', 'Retrovisor Gvs Modelo Original Mt03 Fixo Lente Convexa Rosca Para Honda', 'RETROVISOR GVS ORIGINAL MODELO MOTO COMPATÍVEL COM YAMAHA MT-03 MT-07 MT-09 LENTE CONVEXA HASTE FIXA LADO DISPONÍVEL - Direito - Esquerdo ESPECIFICAÇÃO TECNICA - Cor: Preto - Modelo: Fixo - Lente: Convexa - Marca: GVS Sport - Material: Nylon - Modelo: Yamaha MT-03 / MT-07 / MT-09 - Haste: Preta DETALHES - Alta qualidade e durabilidade - Encaixe perfeito - Fácil instalação - Maior campo de visão ao condutor - Ótimo acabamento - Peso e medida igual ao modelo original - Produto disponível a pronta entrega MEDIDAS - Comprimento Total: 29cm - Medidas do Espelho (A x L): 9cm x 16cm CONTEÚDO EMBALAGEM - 1 Par de retrovisor para moto (Lado direito e esquerdo) IMPORTANTE - Reservamo-nos também o direito de corrigir ou complementar qualquer erro de digitação, publicação ou gráfico. - Não nos responsabilizamos pelo mau uso do produto. - Recomendamos que a instalação seja realizada por profissional qualificado. - Antes de comprar certifique se seu e-mail, endereço e dados estão atualizados dentro da plataforma. - Utilizaremos os seus dados cadastrados para realizar contato e através dele você poderá concluir e acompanhar a compra. - Tire todas as dúvidas no chat da plataforma, temos uma equipe totalmente qualificada e a disposição pronta para ajudar.', 131.99, 117.47, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Side Mirrors', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m59y5bll205s7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482959943%2F20439104589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255151673', 'Placa de Vídeo AsRock RX 9070 XT Steel Legend Dark 16GB GDDR6 256bits - 90-GA5VZZ-00UANF', 'RX 9070 XT Steel Legend Dark Com os LEDs ARGB integrados, você pode criar seus próprios efeitos de iluminação coloridos exclusivos que também podem ser ligados e desligados. Ele também pode ser sincronizado com placas-mãe ASRock que suportam Polychrome SYNC. O design de três ventoinhas ajuda a otimizar o resfriamento do sistema para reduzir a temperatura operacional. Projetado para evitar a curvatura do PCB. A aparência sofisticada torna a placa gráfica mais lendária em termos visuais. Também ajuda a melhorar o resfriamento com as almofadas térmicas premium equipadas na parte traseira. Design Térmico Triple-Fan As três ventoinhas num enorme dissipador de calor proporcionam uma refrigeração silenciosa e eficaz. Especificações Técnicas Marca AsRock Modelo 90-GA5VZZ-00UANF Núcleos 4096 units Memória 16GB GDDR6 Interface de Memória 256 bits Barramento PCIe 5.0 Clock Gráfico 1660MHz Base Clock 2970MHz Boost Clock de Memória 20.1 Gbps Conector de Energia 1x 8pin TDP 304W Conexões 3x DisplayPort 2.1b 1x HDMI 2.1b Resolução Máxima 7680 x 4320 Até 4K 480Hz ou 8K 120Hz Máximo de Monitores 4 G-Sync Sim Direct-X 12 Ultimate OpenGL 4,6 Dimensões 298 x 131 x 58 mm Peso 1155g', 5317.9, 5317.9, NULL, 'Computers & Accessories > Desktop & Laptop Components > Graphics Cards', 'https://cf.shopee.com.br/file/br-11134275-81ztc-mkiisqowyyo31b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1668186272%2F58255151673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
