INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294489605', 'Cavalete para Veículos 2 Toneladas com 10 Posições e Pino Trava Vonder', 'Indicado para veículos. Utilizar somente em superfícies planas e rígidas e nunca exceder a capacidade de carga. Possui estrutura reforçada e 10 posições de ajuste com pino trava. Conteúdo da Embalagem: 1 Cavalete. Detalhes Técnicos • Material do cavalete: Estrutura metálica reforçada • Capacidade: 2 toneladas • Altura mínima: 275 mm • Altura máxima: 425 mm • Número de ajustes de altura do cavalete: 10 posições • Cor do cavalete: Amarelo / Preto • Peso: 2,7 kg • Garantia: 90 dias', 162.88, 159.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Measurement', 'https://cf.shopee.com.br/file/br-11134207-820li-mqrmnv32fmyre3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F23294489605', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
