INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493121063', 'Sanduicheira e Grill Elétrica 2 em 1 Antiaderente Kian Vermelha 750W Sanduíches e Lanches', 'Prepare lanches deliciosos, sanduíches crocantes e grelhados saborosos com praticidade usando a Sanduicheira e Grill 2 em 1 Kian. Com design moderno na cor vermelha, ela combina funcionalidade e eficiência para facilitar o dia a dia na cozinha. Suas placas antiaderentes evitam que os alimentos grudem, facilitando a limpeza e permitindo o preparo com pouco ou nenhum óleo. Compacta e prática, possui capacidade para até 2 sanduíches, luz indicadora de funcionamento, alça com proteção térmica e armazenamento vertical para ocupar menos espaço. Diferenciais do Produto ✔ Função 2 em 1: sanduicheira e grill ✔ Placas com revestimento antiaderente ✔ Preparo com pouco ou nenhum óleo ✔ Capacidade para até 2 sanduíches ✔ Alça com proteção contra calor ✔ Luz indicadora de funcionamento ✔ Armazenamento vertical para economizar espaço ✔ Design moderno e elegante na cor vermelha Ideal para Preparar 🥪 Sanduíches quentes e crocantes 🥩 Carnes grelhadas 🧀 Queijos e lanches variados 🥬 Legumes grelhados 🍔 Hambúrgueres e petiscos Especificações Técnicas Marca: Kian Cor: Vermelha Tipo: Sanduicheira e Grill Elétrica 2 em 1 Revestimento: Antiaderente Capacidade: 2 sanduíches Largura: 24 cm Altura: 22 cm Comprimento: 9 cm Peso: 0,965 kg', 179.0, 79.9, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/sg-11134201-7rd6v-lx9vu9fh9bwm1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F23493121063', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
