INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594542173', 'Freezer Vertical Consul Branco 1 Porta 121 Litros - CVU18GB', 'O Freezer Vertical Consul, 1 Porta, 121 Litros, Branco - CVU18GB é a opção perfeita para você, conta com diversos diferenciais e vai deixar sua cozinha mais moderna e prática, sendo elegante por fora e gigante por dentro, são 121 litros para armazenar todos seus alimentos de forma eficaz, com lugar certo e compartimento de sobra para tudo o que você quiser conservar por mais tempo. Com a Compartimentalização tem o compartimento certo para cada tipo de alimento. O Compartimento para gelo e picolé ajuda a manter o picolé na consistência ideal para o consumo. O Gavetão de frutos do mar, mantendo devidamente organizados e conservados. A Prateleira de pratos prontos é ideal para embalagens congeladas e pratos prontos, além de seus Cestos aramados e deslizantes com trava de segurança oferecem muita Praticidade e segurança no seu dia a dia. Sem contar com sua Classificação Energética classificada como A, muito mais eficiente e muito mais econômica. E conta com sistema de degelo manual, além do controle de temperatura com 3 níveis e seus pés ajustáveis. Características: Tipo: Vertical Capacidade útil: 121,00 litros Capacidade total (litros): 166 litros Cesto: Deslizantes e removíveis Prateleiras: 1 prateleira Livre de CFC: Sim Classificação Energética: A Frequência: 60 Hz Consumo de energia:37 kW/h Conteúdo da embalagem: Freezer e manual de instruções Dimensões: Altura: 129,80 cm Largura:48,30 cm Profundidade: 62,00 cm Peso: 36,00 kg Garantia do Fornecedor: 12 meses Confira as dimensões do produto e verifique se passará pela porta ou elevador do local da entrega.', 2617.86, 2617.86, NULL, 'Home Appliances > Kitchen Appliances > Freezers', 'https://cf.shopee.com.br/file/sg-11134201-825a0-mg2ayf5ttpmycb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1630032069%2F23594542173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498765046', 'Kit Carrinhos Hot Wheels 3 Unidades', 'Agora sua coleção de Carrinhos ficará completa com Kit Hot Wheels Eles são perfeitos para brincadeiras cheias de imaginação, onde as crianças podem criar suas próprias aventuras automobilísticas. Os carrinhos Hot Wheels são mais do que brinquedos: eles incentivam a criatividade, promovem a coordenação motora e inspiram aventuras emocionantes na escala 1:64. Introduzida pela Mattel em 1968, a Hot Wheels é hoje a mais famosa fabricante de carros de brinquedo do mundo! Cada mini coleção tem o tema com os nomes que contam uma história sobre os carros da coleção:veículos temáticos que vão desde muscle cars, carros esportivos, carros de corrida, caminhões e roadsters. Contém detalhes incríveis, como pintura, rodas e acabamento e cada modelo tem sua própria personalidade. Qual o material dos Carrinho Hot Wheels? Os carros de brinquedo são fabricados de die-cast, metal injetado para garantir precisão nos pequenos detalhes. Idade Recomendada: Acima de 3 anos. Atenção: - Sugeito a disponibilidade. - Imagens meramente ilustrativas. As cores podem variar de acordo com a tela/monitor. - O produto pode conter peças pequenas fáceis de serem engolidas. Por este motivo, recomenda-se a supervisão de um adulto. - Envio sortido, sem opção de escolha.', 105.69, 105.69, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-7rdyu-mcqp5tweaqqu3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23498765046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
