INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098050329', 'Mercadinho Confeitaria Infantil Doceria Faz de Conta 62 Peças', 'O mercadinho infantil "Mini Mercado de Sobremesas" é um conjunto de brinquedo projetado para crianças explorarem o faz de conta de forma educativa. Inclui uma mesinha e um total de 62 peças diversas, oferecendo uma ampla variedade de itens de sobremesas em miniatura. Este conjunto promove o desenvolvimento da imaginação, habilidades sociais e coordenação motora das crianças. Ideal para atividades de role-playing, onde os pequenos podem simular cenários de compra e venda, estimulando a criatividade e o aprendizado através da interação com amigos e familiares. A embalagem contém: 1 Mercadinho Infantil desmontado Medidas: 37cm - comprimento 34cm - largura 67cm - altura', 259.9, 129.9, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6qtfpnfq1c7f6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1384111782%2F23098050329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
