INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694742906', 'Areia Higiênica Biodegradável Espaço de Bicho Grãos Grossos 8kg – Milho e Mandioca (100% Natural)', 'A Areia Higiênica Biodegradável Espaço do Bicho é uma opção super premium para a caixa de areia do seu gato, feita de milho e mandioca, com grãos finos e 100% natural. Desenvolvida para oferecer mais praticidade no dia a dia, ela forma torrões firmes, tem rápida absorção e ajuda a manter o ambiente mais limpo por ser livre de poeira. Benefícios: Livre de poeira: contribui para um ambiente mais limpo ao redor da caixa. Rápida absorção: ajuda a controlar a umidade e facilita a rotina. Torrão resistente: forma aglomerados firmes para uma remoção prática. Melhor aceitação: grãos finos que costumam agradar mais aos gatos. Diferenciais: Biodegradável e de origem vegetal (milho e mandioca). Grãos grossos (super premium) para melhor conforto das patinhas. Embalagem econômica de 8kg, ideal para manter a rotina de reposição. Modo de uso: Despeje a areia na bandeja sanitária, formando uma camada de aproximadamente 5 a 7 cm. Diariamente, retire os torrões e resíduos sólidos com uma pá. Complete com mais areia para manter a altura ideal Faça a limpeza completa da bandeja periodicamente (conforme uso), lavando e secando bem antes de reabastecer.', 150.9, 135.89, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mibpf4hxk6pu7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F823664460%2F23694742906', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
