INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51402154972', 'Chinelo Slide Rider Free II Masculino - Bege e Preto', 'O Rider Free II Slide é um slide com design minimalista e estiloso, oferece uma experiência tátil e inspirado em superfícies tecnológicas. Ele apresenta uma gáspea em PVC full plastic, com rolinho, serigrafia interna e acabamento pipetado na lateral. Sua construção em materiais de alta qualidade garante durabilidade e conforto, tornando-o uma escolha ideal para quem busca um slide moderno e funcional. Garanta já o seu!', 89.9, 64.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mizw1k0l0flt82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F51402154972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
