INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994274065', 'Jogo De Escovas De Aço Limpeza Profissional 5 Peças KE500 Para Furadeira E Parafusadeira', 'Distribuído Por Ismafer Ferramentas JOGO DE ESCOVA DE AÇO 5 PEÇAS KE500 OZ O Jogo de Escovas de Aço KE500 da OZ é uma ferramenta altamente versátil, ideal para trabalhos em superfícies irregulares ou ásperas. Seu design especial permite alcançar áreas de difícil acesso, como cantos e o interior de objetos. Pode ser utilizado tanto em furadeiras quanto em retíficas, proporcionando eficiência e praticidade. Além de limpeza, essas escovas também servem para remoção de rebarbas. Características: Dimensões: 1” 25mm , 1-1/2” 38mm , 2” 50mm , 2-1/2” 63mm , 3” 75mm Composição: Aço e metal Velocidade máxima: 4500 RPM Max : 4500 RPM Conteúdo da embalagem: - 01 Jogo de Escovas de Aço com 5 peças Marca: Oz Modelo: KE500 Garantia: 90 Dias SKU:24655 Distribuído Por Ismafer Ferramentas', 45.45, 23.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfviyyckju9z92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F986003177%2F22994274065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
