INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43919408580', 'Kit c/ 12 Pacotes Preservativo Ultra Resistente Prudence', 'O Kit com 12 Pacotes de Preservativos Ultra Resistentes Prudence oferece a máxima proteção aliada ao conforto, proporcionando uma experiência segura e agradável. Cada pacote contém preservativos desenvolvidos com tecnologia avançada para garantir resistência extra, permitindo que você desfrute dos momentos íntimos com confiança e tranquilidade. Benefícios: Ultra Resistência: Estes preservativos foram projetados para serem ultra resistentes, proporcionando uma barreira robusta para uma proteção eficaz. Conforto e Ajuste: A textura e o design foram cuidadosamente pensados para oferecer um ajuste perfeito, maximizando o conforto durante o uso. Segurança Confiável: A marca Prudence é reconhecida por sua qualidade e compromisso com a segurança. Cada preservativo passa por rigorosos padrões de teste para garantir eficácia e resistência. Lubrificação Adequada: Os preservativos vêm com lubrificação adequada, facilitando a colocação e proporcionando uma experiência mais suave. Quantidade Ideal: O kit com 12 pacotes oferece uma quantidade conveniente para garantir que você tenha sempre à mão a proteção necessária. Embalagem Prática: Cada pacote é compacto e fácil de transportar, ideal para levar consigo, garantindo que esteja sempre preparado para priorizar a saúde e a segurança em seus momentos íntimos.', 135.9, 135.9, NULL, 'Health > Others', 'https://cf.shopee.com.br/file/sg-11134201-824if-mer430qj7xfla0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F43919408580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
