INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497491148', 'Máscara Tratamento Creme Luminous Glow Jacques Janine 80g', 'A MÁSCARA LUMINOUS GLOW foi especialmente desenvolvida para devolver o brilho natural aos fios que sofreram algum tipo de dano. Sua fórmula nutritiva com manteiga de murumuru, extrato de pérolas e óleo de monoi, repõe os lipídios perdidos pelos fios, hidratando-os e nutrindo-os, combatendo o frizz e resultando em um cabelo luminoso e cheio de vida. Após lavar os cabelos, aplique a máscara mecha a mecha, deixe agir de 5 a 10 minutos e enxágue Precauções: Uso Externo. Mantenha fora do alcance das crianças. Em caso de alergia a qualquer um dos componentes da fórmula, suspenda o uso. aqua, cetearyl alcohol, glycerin, cetrimonium chloride, glyceryl stearate, behentrimonium chloride, stearamidopropyl dimethylamine, lactic acid, butyrospermum parkii butter, glycerin, hydroxyethyl cetearamidopropyldimonium chloride, behenyl alcohol, polyquaternium-55, cyclopentasiloxane, ceteareth-20, peg-40/ppg-8 methylaminopropyl/hydroxypropyl dimethicone copolymer, corn glycerides, sorbitol, propylene glycol diheptanoate, parfum, orbignya speciosa kernel oil, astrocaryum murumuru seed butter, pearl extract, methylchloroisothiazolinone, methylisothiazolinone, disodium edta, cocos nucifera oil, gardenia taitensis flower extract, bht.', 35.9, 28.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdvt-lygj0zrv5nxw85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F23497491148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
