INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255471908', 'Bota Dakota de Cano Curto Feminina D2191', 'Produto marca Dakota. Eleve seu visual com a Bota Dakota de Cano Curto, a união de design minimalista e com o brilho que transforma o básico em extraordinário. Desenvolvida em material sintético de alta qualidade e com um salto bloco de 7 cm, ela oferece a estabilidade que você precisa para transitar do escritório ao happy hour com total confiança. o fechamento em zíper lateral garante um calce fácil e prático, ideal para a mulher dinâmica que não abre mão da agilidade no dia a dia. O grande diferencial deste modelo é a delicada tira cravejada de brilhos que contorna o cano de 14 cm de altura e 22 cm de circunferência, adicionando um ponto de luz estratégico e uma sofisticação sutil às suas produções. É o calçado indispensável para quem busca versatilidade: combine com jeans para um look casual chic ou com vestidos para uma estética mais elaborada. Mais do que uma bota , é um acessório de moda que comunica personalidade e elegância sem esforço. Invista em um item durável que une conforto e tendência. Com peso leve de 0,780 kg e acabamento impecável, a Bota Dakota foi projetada para acompanhar seu ritmo, garantindo que você esteja sempre pronta para qualquer ocasião de lazer ou trabalho. Garanta a sua e sinta o poder de um calçado que valoriza seu estilo de vida e destaca sua presença por onde passar. Peso: 0,780 kg Altura do cano: 14,0 cm Altura do salto: 7,0 cm Circunferência do cano: 22,0 cm', 287.9, 229.9, NULL, 'Women Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-8262y-mkwufiv2z66d6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F58255471908', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
