INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10116930845', 'CATRACA RODA LIVRE 7V ROSCA INDEX 14-28D', '🚴‍♂️ CATRACA 7 VELOCIDADES – DESEMPENHO E CUSTO-BENEFÍCIO A Catraca Roda Livre 7v com rosca indexada (14-28 dentes) é ideal para quem busca trocas de marcha suaves, durabilidade e ótimo custo-benefício. Perfeita para reposição em bicicletas com sistema 21 velocidades (3x7), garantindo bom desempenho no uso urbano e trilhas leves. 🔧 PRINCIPAIS BENEFÍCIOS • Sistema indexado – trocas mais precisas • Relação 14-28 dentes • Compatível com sistemas 21v (3x7) • Fácil instalação (rosca) • Ideal para MTB e urbano 📌 ESPECIFICAÇÕES TÉCNICAS Tipo: Catraca / roda livre Velocidades: 7v Fixação: Rosca Relação: 14-28 dentes Sistema: Indexado Aplicação: MTB / urbano 🔗 COMPATIBILIDADE ✔ Bicicletas com sistema 21 velocidades (3x7) ✔ Cubos com rosca (não cassete) ✔ Aro 26 / 27.5 / 29 📦 CONTEÚDO DA EMBALAGEM • 1 Catraca 7 velocidades 14-28D ❗ INFORMAÇÕES IMPORTANTES • Produto novo e pronta entrega • Acompanha nota fiscal • Necessita ferramenta específica para instalação ❓ FAQ – DÚVIDAS FREQUENTES Serve em qualquer bike? Somente em bikes com cubo de rosca. É compatível com 21 marchas? Sim. Sistema 3x7 (21v). É fácil instalar? Sim, com ferramenta adequada. É resistente? Sim. Boa durabilidade para uso diário. RM BIKES', 83.99, 37.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/edcc0b3835ede6e62f06c0578c2233c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369650932%2F10116930845', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
